window.PCMG_BANK={"exams":{"pcmg2025":{"name":"PCMG · Investigador · 2025","short":"PCMG 2025 · Investigador","year":2025,"contest":"PCMG","board":"FGV","type":"Investigador · Tipo 1 · Branca","date":"2025-01-26","source":"https://conhecimento.fgv.br/sites/default/files/concursos/investigador-de-policia-icns401-tipo-1.pdf","paperPdf":"https://conhecimento.fgv.br/sites/default/files/concursos/investigador-de-policia-icns401-tipo-1.pdf","keySource":"https://conhecimento.fgv.br/sites/default/files/concursos/gabaritodefinitivo_pcgmpinvestigador.pdf","note":"Prova completa de Investigador de Polícia I, aplicada em 26/01/2025. Edital 04/2024, Tipo 1. Gabarito oficial definitivo; questões anuladas não entram na nota. Questões históricas: confira a legislação e o próximo edital.","answerStatus":"definitivo","originalTotal":70},"pcmg2021":{"name":"PCMG · Investigador · 2021","short":"PCMG 2021 · Investigador","year":2021,"contest":"PCMG","board":"FUMARC","type":"Investigador · Tipo 1","date":"2021-12-12","source":"https://arquivos.qconcursos.com/prova/arquivo_prova/89456/fumarc-2021-pc-mg-investigador-de-policia-i-prova.pdf","paperPdf":"https://arquivos.qconcursos.com/prova/arquivo_prova/89456/fumarc-2021-pc-mg-investigador-de-policia-i-prova.pdf","keySource":"https://arquivos.qconcursos.com/prova/arquivo_gabarito/89456/fumarc-2021-pc-mg-investigador-de-policia-i-gabarito.pdf","note":"Prova completa de Investigador de Polícia I, aplicada em 12/12/2021. Edital 05/2021, Tipo 1. Gabarito oficial definitivo; questões anuladas não entram na nota. Questões históricas: confira a legislação e o próximo edital.","answerStatus":"definitivo","originalTotal":60}},"questions":[{"id":"pcmg2025-1","exam":"pcmg2025","number":1,"subject":"Português","text":"Analise o cartaz a seguir.\nSobre o cartaz acima, assinale a afirmativa correta.","options":{"A":"Todas as frases do cartaz estão gramaticalmente corretas.","B":"A frase “que te sustenta” tem valor conclusivo, em relação à frase anterior.","C":"“Beba muita água e evite desperdícios” é um conselho de valor medicinal.","D":"Pela presença da garrafa ao pé do cartaz, nota-se que a água referida é a água mineral.","E":"A presença da borboleta, do beija-flor e da própria flor documentam a vida sustentada pela água."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q1-p2-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-2","exam":"pcmg2025","number":2,"subject":"Português","text":"Assinale a opção que apresenta a frase que documenta a\nlinguagem figurada.","options":{"A":"Serviço sem pagamento é castigo.","B":"Nosso objetivo é dominar o mundo, como a Microsoft.","C":"Pior do que não ter dinheiro é ter dinheiro em excesso.","D":"Um povo só se deixa guiar quando lhe apontam um futuro.","E":"O homem esquece mais facilmente a morte do pai que a perda do patrimônio."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q2-p2-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-3","exam":"pcmg2025","number":3,"subject":"Português","text":"Assinale a opção que indica o texto classificado como descritivo.","options":{"A":"Seja feliz!","B":"A riqueza é a felicidade na Terra.","C":"Trabalhe sempre e muito e ficará rico.","D":"Nunca deixe para hoje o que pode fazer amanhã.","E":"Trabalhei muito, economizei bastante, fiquei rico."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q3-p2-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-4","exam":"pcmg2025","number":4,"subject":"Português","text":"Assinale a frase que está expressa em discurso indireto.","options":{"A":"O capital é trabalho roubado.","B":"Fazer bons negócios é ver primeiro que os demais.","C":"Quer que seus negócios continuem bem? Faça-os você.","D":"Já foi dito que dinheiro disponível é uma lâmpada de Aladim.","E":"Quando o assunto é dinheiro, todos os homens pertencem à mesma religião."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q4-p2-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-5","exam":"pcmg2025","number":5,"subject":"Português","text":"Os adjetivos em Língua Portuguesa expressam estados,\nqualidades, características e relações; assinale a opção em que o\nadjetivo sublinhado mostra um estado.","options":{"A":"País feliz.","B":"Homem alto.","C":"Mesa arranhada.","D":"Produto importado.","E":"Discurso presidencial."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q5-p2-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-6","exam":"pcmg2025","number":6,"subject":"Português","text":"Em todas as frases a seguir foi indicada uma inferência, ou seja,\nalgo que pode ser deduzido da leitura.\nAssinale a opção que apresenta a frase em que a dedução é\ninadequada.","options":{"A":"O Flamengo ganhou o campeonato mundial. / O time do Flamengo é magnífico.","B":"As mulheres já podem servir nas Forças Armadas. / As mulheres mostram ascensão na sociedade.","C":"Muita gente no Rio de Janeiro vive nas favelas. / As favelas do Rio são lugares aprazíveis.","D":"Uma multidão atacou o supermercado de alimentos. / O país atravessa uma crise social.","E":"A temperatura no estádio atingiu 40 graus. / O futebol devia alterar alguns horários de partidas."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q6-p2-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-7","exam":"pcmg2025","number":7,"subject":"Português","text":"Observe o seguinte ato comunicativo:\nO gerente da loja pegou o cartaz feito pela empresa de publicidade\ncontratada\ne\no\ncolocou\nna\nentrada\nda\nloja.\nA promessa de preços mais baixos deveria atrair clientes, promessa\nessa ajudada pelas belas imagens das camisas.\nSobre esse ato, assinale a afirmativa inadequada.","options":{"A":"O emissor do cartaz é o gerente da loja.","B":"A mensagem do cartaz é de tipo publicitário.","C":"O código empregado é feito de palavras e imagens.","D":"Os receptores pretendidos são possíveis clientes.","E":"Preços mais baixos são argumento para a venda."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q7-p2-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-8","exam":"pcmg2025","number":8,"subject":"Português","text":"Nas frases abaixo, o termo sublinhado foi substituído por outro\ntermo, indicado ao final da frase.\nAssinale a opção em que esse novo termo é intensificador do\nanterior.","options":{"A":"Ela ficou magra após a dieta. / abatida.","B":"Ele se separou da esposa. / abandonou.","C":"As páginas do livro grudaram. / se uniram.","D":"Após o acidente, ela ficou pálida. / apavorada.","E":"O aluno rabiscou as páginas do livro. / escreveu."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q8-p2-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-9","exam":"pcmg2025","number":9,"subject":"Português","text":"As frases a seguir tentam tornar suas informações mais precisas.\nA forma de fazer isso que não está corretamente indicada, é:","options":{"A":"As medidas propostas – redução de impostos, demissão de funcionários, abandono de projetos – não foram bem recebidas / enumeração.","B":"Nesse nosso imenso país – quatorze vezes maior que a França – os casos de escravidão são raríssimos / elemento informativo acidental.","C":"Três mil e cem de pessoas manifestaram seu protesto / quantificação precisa.","D":"O empresário Henry Ford defendia a divisão de tarefas / o emprego de nomes próprios.","E":"Não se trata das importações, mas das exportações / utilização de palavras de sentido próximo."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q9-p3-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-10","exam":"pcmg2025","number":10,"subject":"Português","text":"Procurando reduzir a extensão dos textos, em todas as frases\nabaixo as orações substantivas sublinhadas foram substituídas por\nsubstantivos.\nAssinale a opção em que isso foi feito de forma adequada.","options":{"A":"Quem não escuta é feliz. / o surdo-mudo.","B":"Quem vive sozinho não conversa. / o solitário.","C":"Quem não se casou perde tempo na vida. / o viúvo.","D":"Quem vive pedindo na rua se vicia. / o desempregado.","E":"Quem vive de herança pode descansar. / o preguiçoso."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q10-p3-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-11","exam":"pcmg2025","number":11,"subject":"Raciocínio Lógico-Matemático","text":"Durante uma operação da polícia civil para investigar fraudes\nfiscais, constatou-se que, em uma amostra de 600 documentos\nanalisados, 55% apresentaram indícios de irregularidades.\nAo examinar mais detalhadamente esses documentos com\nindícios, apurou-se que 30% dos valores neles declarados foram\nfraudados. Além disso, desses valores fraudulentos, um terço\ncorrespondeu a fraudes envolvendo notas “frias” emitidas por\nempresas fictícias.\nCom base nessas informações, o número total de documentos\nanalisados que apresentaram indícios e que envolvem fraudes\nrelacionadas a notas “frias” emitidas por empresas fictícias é","options":{"A":"30.","B":"32.","C":"33.","D":"35.","E":"36."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q11-p3-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-12","exam":"pcmg2025","number":12,"subject":"Raciocínio Lógico-Matemático","text":"Uma delegacia recebeu, no mês de dezembro de 2024, denúncias\nrelacionadas a três tipos de crimes: roubo, fraude eletrônica e\ntráfico de drogas.\nApós uma triagem, constatou-se que:\n•\n44% das denúncias são sobre roubos;\n•\n36% das denúncias são sobre fraudes eletrônicas;\n•\n20% das denúncias são sobre tráfico de drogas.\nHistoricamente, sabe-se que 30% das denúncias contra fraudes\neletrônicas são improcedentes, assim como 10% das denúncias\ncontra roubo e 20% das denúncias contra tráfico de drogas.\nSe uma denúncia é escolhida ao acaso, a probabilidade de ela ser\ncontra roubo, sabendo-se que é uma denúncia procedente, é de\naproximadamente","options":{"A":"50%.","B":"49%.","C":"48%.","D":"47%.","E":"46%."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q12-p3-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-13","exam":"pcmg2025","number":13,"subject":"Raciocínio Lógico-Matemático","text":"A polícia civil recebeu um relatório sobre o número de ocorrências\nregistradas em uma delegacia ao longo de um mês.\nA tabela a seguir apresenta dados parciais sobre as quantidades de\nocorrências e o número de casos solucionados para diferentes\ntipos de crimes:\nTipo de Crime\nOcorrências\nCasos Solucionados\nRoubo\n180\n135\nTráfico de Drogas\n45\nEstelionato\n120\nLesão Corporal\n30\nSabendo-se que a proporção de casos solucionados em relação às\nocorrências é a mesma para cada tipo de crime, pode-se concluir\ncorretamente que as ocorrências de roubo, com relação ao total\nde ocorrências registradas, correspondem a","options":{"A":"45%.","B":"48%.","C":"50%.","D":"54%.","E":"55%."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q13-p3-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-14","exam":"pcmg2025","number":14,"subject":"Raciocínio Lógico-Matemático","text":"Em uma investigação, a quantidade de policiais trabalhando é\ninversamente proporcional ao tempo necessário para a sua\nconclusão. Se houvesse apenas três policiais desde o início da\ninvestigação, o tempo para a sua conclusão seria de 20 dias.\nA inclusão de um policial a mais no início da investigação permitiria\nque a conclusão do trabalho fosse antecipada em","options":{"A":"um dia.","B":"dois dias.","C":"três dias.","D":"quatro dias.","E":"cinco dias."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q14-p3-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-15","exam":"pcmg2025","number":15,"subject":"Raciocínio Lógico-Matemático","text":"Uma delegacia de polícia está investigando uma série de quatro\nataques a caixas eletrônicos ocorridos em diferentes localidades\nda cidade. Os policiais que conduzem a investigação identificaram\nque os criminosos aparentemente seguem um padrão de ataque\nbaseado em dias específicos e em distâncias da delegacia.\nO histórico dos ataques é o seguinte:\n•\n1º ataque: domingo, dia 1º de dezembro, a 5 km da delegacia.\n•\n2º ataque: terça-feira, dia 3 de dezembro, a 6 km da delegacia.\n•\n3º ataque: sexta-feira, dia 6 de dezembro, a 8 km da delegacia.\n•\n4º ataque: terça-feira, dia 10 de dezembro, a 11 km da\ndelegacia.\nCom base no padrão identificado, provavelmente o próximo\nataque, se ocorrer, acontecerá","options":{"A":"na sexta-feira, dia 13 de dezembro, a 13 km da delegacia.","B":"no sábado, dia 14 de dezembro, a 15 km da delegacia.","C":"no sábado, dia 15 de dezembro, a 16 km da delegacia.","D":"no domingo, dia 15 de dezembro, a 15 km da delegacia.","E":"no domingo, dia 16 de dezembro, a 14 km da delegacia."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q15-p4-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-16","exam":"pcmg2025","number":16,"subject":"Raciocínio Lógico-Matemático","text":"Um policial civil está analisando os tempos de resposta de\ndiferentes equipes em várias ocorrências. Ele solicitou a coleta dos\ntempos de resposta de oito patrulhas, em minutos, e recebeu um\nrelatório com tais registros e a mediana, já calculada, do conjunto\nde valores.\nNo entanto, ao ler o relatório, percebeu que um dos valores estava\nilegível, como ilustrado a seguir:\nCom base nos dados fornecidos, ele conseguiu recuperar o valor\nilegível e, com isso, calculou, corretamente, a média desse\nconjunto de valores.\nO valor que o policial obteve para a média foi","options":{"A":"27,00.","B":"27,25.","C":"27,50.","D":"28,00.","E":"28,15."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q16-p4-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-17","exam":"pcmg2025","number":17,"subject":"Informática","text":"Com o crescimento da internet ao longo dos anos, a quantidade de\nendereços IP disponíveis no protocolo IPv4 tornou-se insuficiente.\nPara solucionar esse problema e incorporar outras melhorias\ntecnológicas, o protocolo IPv6 foi desenvolvido como sucessor do\nIPv4.\nNo contexto dos protocolos de internet IPv4 e IPv6, assinale a\nafirmativa correta.","options":{"A":"O IPv4 utiliza endereços de 64 bits, enquanto o IPv6 utiliza endereços de 128 bits.","B":"O IPv6 elimina completamente a necessidade de NAT (Network Address Translation).","C":"O IPv4 oferece maior eficiência no roteamento, pois possui cabeçalhos menores que o IPv6.","D":"O IPv6 inclui o suporte nativo a funcionalidades como segurança e mobilidade, que são apenas opcionais no IPv4.","E":"O IPv6 permite até quatro vezes mais endereços únicos do que o IPv4."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q17-p4-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-18","exam":"pcmg2025","number":18,"subject":"Informática","text":"No início da Internet, as redes eram predominantemente\ncabeadas. Com a crescente demanda por mobilidade, as redes sem\nfio (Wi-Fi) surgiram e se tornaram amplamente utilizadas, tanto\nnos ambientes corporativos quanto nos ambientes domésticos.\nConsidere os aspectos técnicos e operacionais de redes com fio\n(Ethernet) e redes sem fio.\nAssinale a opção que apresenta uma comparação tecnicamente\ncorreta e mais abrangente entre essas duas tecnologias.","options":{"A":"Redes sem fio alcançam taxas de latência menores que redes com fio devido à ausência de infraestrutura física de cabeamento.","B":"Redes com fio oferecem maior estabilidade, largura de banda e segurança física, enquanto redes sem fio priorizam mobilidade e flexibilidade de implantação.","C":"Redes sem fio são imunes a interferências de dispositivos externos devido à utilização de canais exclusivos para transmissão de dados.","D":"Redes com fio utilizam cabeamento coaxial como padrão principal, enquanto redes sem fio operam exclusivamente na frequência de 2,4 GHz para evitar congestionamento.","E":"Redes sem fio oferecem maior largura de banda e maior alcance em comparação às redes com fio devido ao uso de ondas de rádio para transmissão."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q18-p4-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-19","exam":"pcmg2025","number":19,"subject":"Informática","text":"Processadores de texto são programas de computador projetados\npara criar, editar, formatar e imprimir documentos textuais. Eles\nsão amplamente utilizados em diversos contextos, como no\nambiente profissional, acadêmico e pessoal, devido à sua\ncapacidade de produzir documentos bem estruturados de forma\neficiente.\nApesar de termos uma variedade de opções no mercado, os\neditores de texto mais famosos e mais utilizados são o Microsoft\nWord e LibreOffice Writer. O Microsoft Word e o LibreOffice\nWriter possuem funcionalidades semelhantes para facilitar a\nformatação de documentos.\nAs opções a seguir apresentam funcionalidades comuns nativas\nentre os dois softwares, à exceção de uma. Assinale-a.","options":{"A":"Inserção de tabelas para a organização de dados.","B":"Aplicação de estilos para formatar títulos e parágrafos.","C":"Inserção de mala direta para o envio de documentos personalizados.","D":"Colaboração em tempo real com múltiplos usuários diretamente no arquivo.","E":"Exportação de documentos no formato PDF."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q19-p5-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-20","exam":"pcmg2025","number":20,"subject":"Informática","text":"Planilhas eletrônicas são programas projetados para criar, organizar,\ncalcular e analisar dados em formato tabular. Elas são amplamente\nutilizadas para tarefas que vão desde cálculos simples até análises\ncomplexas, sendo uma ferramenta essencial em áreas como\nfinanças, gestão, estatística, ciência de dados e muitas outras.\nExistem várias opções no mercado, sendo os mais famosos e\nutilizados o Microsoft Excel e o LibreOffice Calc. No Microsoft Excel\ne no LibreOffice Calc, é possível realizar diversas operações para a\nmanipulação e análise de dados.\nAssinale a funcionalidade que não é nativamente suportada por\nambos os softwares.","options":{"A":"Criação de gráficos a partir de dados em planilhas.","B":"Aplicação de filtros automáticos em tabelas.","C":"Uso de tabelas dinâmicas para sumarização de dados.","D":"Programação de macros em Python.","E":"Importação de arquivos CSV para edição."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q20-p5-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-21","exam":"pcmg2025","number":21,"subject":"Informática","text":"Um malware (abreviação de malicious software, ou “software\nmalicioso”) é qualquer programa ou código projetado para\nprejudicar, explorar ou comprometer dispositivos, redes ou\nusuários. Ele pode roubar informações, causar danos ao sistema,\nespionar atividades ou obter controle de dispositivos sem a\npermissão do usuário. Entre os tipos principais de malware\npodemos citar worm, cavalo de Troia, spyware, adware, phishing,\nbotnets, entre outros.\nAssinale a opção que descreve corretamente a principal diferença\nentre um worm e um cavalo de Troia.","options":{"A":"Worms dependem de um programa legítimo para se espalhar, enquanto cavalos de Troia são autônomos e se replicam automaticamente.","B":"Worms podem se replicar automaticamente e se espalhar por redes, enquanto cavalos de Troia precisam ser instalados pelo usuário como se fossem programas legítimos.","C":"Worms roubam informações sensíveis sem o conhecimento do usuário, enquanto cavalos de Troia criptografam dados para pedir resgate.","D":"Worms não causam danos diretos, enquanto cavalos de Troia são exclusivamente destrutivos.","E":"Worms exigem interação do usuário para ativação, enquanto cavalos de Troia se propagam sem necessidade de ação humana."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q21-p5-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-22","exam":"pcmg2025","number":22,"subject":"Informática","text":"João, um profissional de TI, recebeu um e-mail com o título\n“Atualize sua senha agora para evitar bloqueio de conta”.\nO e-mail continha um link que levava a uma página idêntica ao site\nde sua instituição bancária, onde ele inseriu suas credenciais.\nDias depois, João percebeu que sua conta havia sido acessada sem\nautorização, resultando em um prejuízo financeiro.\nCom base na situação descrita, assinale a opção que classifica\ncorretamente o ataque cibernético sofrido por João.","options":{"A":"Ransomware, pois houve uma tentativa de bloqueio do acesso à conta de João, o que caracteriza o ataque.","B":"Phishing, pois o atacante usou um e-mail fraudulento para capturar as credenciais de João.","C":"DoS (Denial of Service), já que a conta de João foi acessada sem autorização, prejudicando o serviço.","D":"Spoofing, porque João foi induzido a revelar informações sensíveis.","E":"Malware, porque o e-mail provavelmente continha um programa malicioso que invadiu o sistema de João."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q22-p5-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-23","exam":"pcmg2025","number":23,"subject":"Informática","text":"Considere o uso de criptografia assimétrica em uma transação\nonline. Maria deseja enviar uma mensagem confidencial para\nJoão, garantindo que apenas ele possa ler o conteúdo.\nPara que essa segurança seja alcançada, Maria deve criptografar a\nmensagem","options":{"A":"usando a chave privada dela, garantindo que apenas João consiga descriptografar.","B":"usando a chave pública de João, garantindo que somente João possa descriptografar com sua chave privada.","C":"usando a chave pública dela, para que João possa descriptografar com sua chave privada.","D":"com a chave privada de João, pois apenas João poderá descriptografá-la com sua chave pública.","E":"com uma chave simétrica gerada por João, garantindo que ambos tenham acesso à mesma chave."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q23-p5-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-24","exam":"pcmg2025","number":24,"subject":"Informática","text":"As licenças BSD, GPLv2 e GPLv3 possuem diferenças importantes\nquanto às permissões e restrições no uso, na modificação e na\nredistribuição de software.\nAssinale a opção que descreve corretamente uma característica\ndistintiva entre essas licenças.","options":{"A":"A licença BSD exige que qualquer redistribuição de código modificado seja feita sob a mesma licença, assim como as licenças GPLv2 e GPLv3.","B":"A GPLv3 introduz cláusulas adicionais para proteção contra práticas como a implementação de DRM (Digital Rights Management), o que não é abordado pela GPLv2.","C":"As licenças BSD e GPLv2 possuem a mesma abordagem em relação à obrigatoriedade de compartilhar modificações do código.","D":"A GPLv3 permite que o software licenciado sob a GPLv2 seja automaticamente compatível com a nova versão, independentemente do termo, ou qualquer versão posterior.","E":"A licença BSD impede explicitamente o uso do software em projetos proprietários, o que a diferencia das licenças GPLv2 e GPLv3."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q24-p5-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-25","exam":"pcmg2025","number":25,"subject":"Lei Orgânica da PCMG","text":"João e Matheus, investigadores de polícia e integrantes de um\nmesmo Departamento da Polícia Civil do Estado de Minas Gerais\n(PCMG), estão interessados em realizar remoção por permuta.\nNesse cenário, considerando as disposições da Lei Complementar\nEstadual nº 129/2013, a remoção de investigadores de polícia por\npermuta, nos limites de determinado Departamento de Polícia\nCivil, ingressa na competência da","options":{"A":"Superintendência de Informações e Inteligência Policial.","B":"Superintendência de Planejamento, Gestão e Finanças.","C":"Superintendência de Investigação e Polícia Judiciária.","D":"Corregedoria-Geral de Polícia Civil.","E":"Chefia Adjunta da PCMG."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q25-p6-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-26","exam":"pcmg2025","number":26,"subject":"Lei Orgânica da PCMG","text":"O Corregedor-Geral de Polícia Civil ministrou palestra aos novos\npoliciais civis da PCMG, abordando, entre outros tópicos, a\ntemática disciplinar, dando enfoque às penalidades previstas\nem lei.\nDe acordo com a narrativa, avalie as afirmativas a seguir.\nI.\nAusência do serviço, sem causa justificável, por mais de\n30 dias, interpoladamente, durante um ano.\nII. Exercício de qualquer atividade remunerada, estando o\nservidor licenciado para tratamento de saúde.\nIII. Procedimento irregular de natureza grave.\nConsiderando as disposições da Lei Estadual nº 5.406/1969, será\naplicada a pena de demissão na hipótese(s) elencada(s) em","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q26-p6-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-27","exam":"pcmg2025","number":27,"subject":"Lei Orgânica da PCMG","text":"Lucas, policial civil do Estado de Minas Gerais, responde, na esfera\nadministrativa, por ter praticado, em tese, transgressão\ndisciplinar.\nApós a observância do contraditório e da ampla defesa,\nconstatou-se que existia, no caso apresentado, uma causa\njustificante, influindo no julgamento em andamento.\nNesse cenário, considerando as disposições da Lei Estadual\nnº 5.406/1969, assinale a opção que apresenta uma causa\njustificante.","options":{"A":"Ter o transgressor confessado, espontaneamente, a falta perante a autoridade sindicante.","B":"Apresentar motivo de força maior plenamente comprovado e justificado.","C":"Ter sido cometida a transgressão para evitar mal maior.","D":"Ter bom comportamento anterior.","E":"Ter prestado serviços relevantes."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q27-p6-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-28","exam":"pcmg2025","number":28,"subject":"Lei Orgânica da PCMG","text":"Aos integrantes das carreiras da PCMG, de acordo com a Lei\nComplementar Estadual nº 129/2013, serão atribuídas verbas\nindenizatórias e de gratificação, observados os respectivos\ncritérios e requisitos.\nNesse caso, considerando as disposições da Lei Complementar\nEstadual nº 129/2013, avalie se serão atribuídas aos policiais civis\ndo Estado de Minas Gerais as seguintes verbas:\nI.\nAuxílio-natalidade, devido pelo nascimento de filho ou adoção,\nno valor da remuneração percebida pelo servidor na ocasião\ndo nascimento ou da adoção, a ser paga à vista de certidão,\nadmitida uma única percepção no caso de pai e mãe serem dos\nquadros da PCMG.\nII. Ajuda de custo, em caso de remoção de ofício ou a pedido ou\ndesignação para serviço ou estudo que importe em alteração\ndo domicílio, no valor de um mês de vencimento do servidor.\nIII. Translado ou remoção quando ferido, acidentado ou falecido\nem serviço.\nEstá correto o que se apresenta em","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e III, apenas.","E":"I, II e III."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q28-p6-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-29","exam":"pcmg2025","number":29,"subject":"Lei Orgânica da PCMG","text":"Carlos, policial civil do Estado de Minas Gerais, pretende afastar-\nse de suas funções, sem prejuízo da remuneração, com o objetivo\nde frequentar determinado curso. Para tanto, o referido agente\npúblico buscou informações na legislação que trata da matéria.\nDe acordo com a narrativa, avalie as afirmativas a seguir.\nI.\nO Chefe da PCMG poderá conceder afastamento ao policial\ncivil, sem prejuízo da remuneração, para frequentar cursos\nrelacionados com o exercício das funções do cargo ocupado\npelo policial civil, pelo prazo de seis meses, prorrogável até o\nmáximo de seis meses.\nII. O policial civil que tenha se afastado das funções para estudo,\nespecialização\nou\naperfeiçoamento,\nsem\nprejuízo\nda\nremuneração ou com ônus para a PCMG, ficará obrigado a\nprestar serviços pelo menos por mais cinco anos após o\nperíodo do afastamento ou a ressarcir o Estado da importância\ndespendida, inclusive com o custeio da viagem, em\nconformidade com o disposto em regulamento.\nIII. O policial civil afastado não pode exercer nenhuma de suas\nfunções, ou outra, pública ou particular, diversa da que\nmotivou o ato, sob pena de cassação do ato de afastamento e\ndo imediato retorno às atividades.\nNesse cenário, considerando as disposições da Lei Complementar\nEstadual nº 129/2013, está correto o que se afirma em","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q29-p6-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-30","exam":"pcmg2025","number":30,"subject":"Lei Orgânica da PCMG","text":"Matheus tomou conhecimento, por determinação do seu superior\nhierárquico, de que integrará comissão responsável pelo\nprocessamento de um pedido de revisão de pena aplicada no bojo\nde determinado processo administrativo disciplinar, sob o\nfundamento de que a decisão tomada foi contrária ao texto\nexpresso na lei.\nDessa forma, o referido agente público resolveu analisar a\nlegislação de regência, com o objetivo de se atualizar sobre o\ninstituto da revisão de processo administrativo.\nNesse cenário, considerando as disposições da Lei Estadual\nnº 5.406/1969 (Lei Orgânica da Polícia Civil do Estado de Minas\nGerais), assinale a afirmativa incorreta.","options":{"A":"A revisão poderá ser pedida pelo próprio punido ou por procurador legalmente habilitado, vedada, em caso de morte, a postulação por cônjuge sobrevivente.","B":"Aquele que houver integrado a comissão de processo administrativo será impedido de atuar na revisão.","C":"A Administração, julgada procedente a revisão, determinará a redução ou o cancelamento da pena.","D":"A revisão, que poderá verificar-se a qualquer tempo, não autoriza a agravação da pena.","E":"A simples alegação de injustiça da penalidade não constitui fundamento para revisão."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q30-p7-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-31","exam":"pcmg2025","number":31,"subject":"Direito Administrativo","text":"Antes de ser nomeado e empossado na qualidade de inspetor de\npolícia, Lucas, com o objetivo de melhor entender as funções que\nfuturamente desempenhará, resolveu analisar como a Polícia Civil\ndo Estado de Minas Gerais está inserida no contexto da\nAdministração Pública.\nConsiderando os entendimentos doutrinário e jurisprudencial\ndominantes, é correto afirmar que a Polícia Civil do Estado de\nMinas Gerais é","options":{"A":"um órgão público, integrante da Administração Pública Direta, fruto da desconcentração administrativa.","B":"um órgão público, integrante da Administração Pública Direta, fruto da descentralização administrativa.","C":"um órgão público, integrante da Administração Pública Indireta, fruto da desconcentração administrativa.","D":"uma autarquia, integrante da Administração Pública Indireta, fruto da desconcentração administrativa.","E":"uma autarquia, integrante da Administração Pública Indireta, fruto da descentralização administrativa."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q31-p7-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-32","exam":"pcmg2025","number":32,"subject":"Direito Administrativo","text":"Durante o cumprimento de uma diligência externa, determinada\npela autoridade policial, Carlos, policial civil do Estado de Minas\nGerais, agindo de forma negligente, acabou por atropelar um\ntranseunte. Registre-se que, realizada perícia no local dos fatos,\nconstatou-se que o pedestre não teve qualquer culpa para o\nadvento do resultado danoso.\nConsiderando\nas\ndisposições\nda\nConstituição\nFederal\ne\nos entendimentos doutrinário e jurisprudencial dominantes, avalie as\nafirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa.\n(   ) O Estado de Minas Gerais poderá ser responsabilizado,\nsubsidiariamente, em razão da conduta praticada por Carlos,\ncaso este não tenha capacidade para arcar com eventual\nindenização fixada em benefício do transeunte.\n(   ) A responsabilidade civil de Carlos, na qualidade de agente\npúblico, é objetiva, pressupondo-se a demonstração do\nelemento anímico.\n(   ) Para que a responsabilidade civil do Estado de Minas Gerais\npossa ser invocada, é necessário que se demonstre, em juízo,\nno que consistiu a conduta negligente de Carlos.\nAs afirmativas são, respectivamente,","options":{"A":"V – F – V.","B":"F – F – F.","C":"V – V – F.","D":"F – V – F.","E":"V – V – V."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q32-p7-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-33","exam":"pcmg2025","number":33,"subject":"Direito Administrativo","text":"Após ser aprovado em concorrido concurso público, José passará,\nem breve, a atuar na qualidade de inspetor de polícia da Polícia\nCivil do Estado de Minas Gerais.\nNesse cenário, considerando os entendimentos doutrinário e\njurisprudencial dominantes, é correto afirmar que José será um\nservidor público","options":{"A":"estatutário, espécie de agente público de fato, ocupante de um emprego público.","B":"estatutário, espécie de agente público de direito, ocupante de um emprego público.","C":"estatutário, espécie de agente público de direito, ocupante de um cargo público.","D":"celetista, espécie de agente público de direito, ocupante de um cargo público.","E":"celetista, espécie de agente público de fato, ocupante de um cargo público."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q33-p7-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-34","exam":"pcmg2025","number":34,"subject":"Direito Administrativo","text":"Após longa investigação, a Polícia Civil apurou que o agente\npúblico João, em março de 2024, agindo com dolo, teria percebido\nvantagem econômica direta para facilitar a contratação de serviços\npor preço superior ao valor de mercado, por parte do Estado de\nMinas Gerais.\nDe acordo com a narrativa e considerando as disposições da\nLei nº 8.429/1992, analise as afirmativas a seguir.\nI.\nJoão praticou ato de improbidade administrativa que importa\nenriquecimento ilícito.\nII. No curso da ação judicial, será assegurado a João o direito de\nser interrogado sobre os fatos de que trata a demanda, e a sua\nrecusa ou o seu silêncio não implicarão confissão.\nIII. Em caso de condenação em primeira instância, a sentença de\nprocedência estará sujeita ao instituto do reexame\nobrigatório.\nEstá correto o que se afirma em","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e II, apenas.","E":"I, II e III."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q34-p7-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-35","exam":"pcmg2025","number":35,"subject":"Direito Administrativo","text":"A autoridade competente, no âmbito da Polícia Civil de Minas\nGerais, editou um decreto, com o objetivo de esmiuçar\ndeterminada legislação aprovada pela Assembleia Legislativa e\nsancionada pelo Governador do Estado, aplicável à referida\ninstituição policial.\nRegistre-se que, após alguns meses, descobriu-se que João, policial\ncivil, havia descumprido, dolosamente, diversas determinações\nexistentes no decreto. Com efeito, após a observância do\ncontraditório e da ampla defesa, o agente público foi punido na\nesfera administrativa.\nNesse cenário, considerando os entendimentos doutrinário e\njurisprudencial dominantes, é correto afirmar que o decreto\neditado pela autoridade competente, no âmbito da Polícia Civil de\nMinas Gerais,","options":{"A":"é uma manifestação do poder regulamentar. Por sua vez, a punição suportada por João é fruto do poder disciplinar.","B":"é uma manifestação do poder regulamentar. Por sua vez, a punição suportada por João é fruto do poder de polícia.","C":"é uma manifestação do poder hierárquico. Por sua vez, a punição suportada por João é fruto do poder de polícia.","D":"é uma manifestação do poder de polícia. Por sua vez, a punição suportada por João é fruto do poder disciplinar.","E":"e a punição suportada por João são manifestações do poder de polícia."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q35-p8-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-36","exam":"pcmg2025","number":36,"subject":"Direito Administrativo","text":"Fábio, agente público, tomou conhecimento de que existe uma\ninvestigação em curso em seu detrimento, em razão da suposta\nprática de ato doloso de improbidade administrativa.\nO referido servidor, além de entrar em contato com um(a)\nadvogado(a), passou a buscar informações junto à legislação de\nregência, em especial porque ele já teria sido punido pelo órgão\nde controle interno da sua instituição.\nDe acordo com a narrativa e considerando as disposições da\nLei nº 8.429/1992, analise as afirmativas a seguir.\nI.\nNa apuração dos ilícitos previstos na Lei de Improbidade\nAdministrativa, será garantido ao investigado a oportunidade\nde manifestação por escrito e de juntada de documentos que\ncomprovem suas alegações e auxiliem na elucidação dos fatos.\nII. As provas produzidas perante os órgãos de controle e as\ncorrespondentes decisões deverão ser consideradas na\nformação da convicção do Juiz, sem prejuízo da análise acerca\ndo dolo na conduta do agente.\nIII. As sanções eventualmente aplicadas em outras esferas\ndeverão ser compensadas com as sanções aplicadas nos\ntermos da Lei de Improbidade Administrativa.\nEstá correto o que se afirma em","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e III, apenas.","E":"I, II e III."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q36-p8-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-37","exam":"pcmg2025","number":37,"subject":"Direito Constitucional","text":"Após amplos estudos realizados pelo Ministério competente, foi\nsugerido ao Presidente da República a apresentação de projeto de\nlei\nestabelecendo\numa\npolítica\npública\nespecificamente\ndirecionada a duas regiões do país, fundada em níveis de\ndesenvolvimento humano, o que redundaria em direcionamento\ndiferenciado de recursos e tratamento mais favorecido, quando\ncotejado com aquele dispensado às demais regiões.\nO presidente do partido político Alfa, que tem grande penetração\nnas regiões preteridas, solicitou que sua assessoria analisasse a sua\ncompatibilidade com os objetivos fundamentais da República\nFederativa do Brasil.\nA assessoria esclareceu corretamente que a proposta","options":{"A":"não possui conformidade constitucional por destoar do objetivo fundamental de garantir o desenvolvimento nacional.","B":"deve ser veiculada por meio de emenda constitucional, de modo a excepcionar a exigência de tratamento igualitário entre os entes federativos.","C":"afronta a concepção de igualdade formal que deve reger o Estado de Direito, legitimando distinções de caráter arbitrário que buscarão amparo no subjetivismo do gestor.","D":"é expressamente vedada pela ordem constitucional, que exige uniformidade das políticas públicas promovidas por cada ente federativo no interior do seu território.","E":"se ajusta ao objetivo fundamental de reduzir as desigualdades sociais e regionais, ainda que redunde em tratamento inicial distinto entre as regiões do país."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q37-p8-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-38","exam":"pcmg2025","number":38,"subject":"Direito Constitucional","text":"De acordo com a Lei Federal nº X, a generalidade das pessoas\nmaiores e capazes, que se encontrem no pleno gozo dos seus\ndireitos políticos, deveria participar de determinada atividade de\ninteresse coletivo desenvolvida pelas estruturas estatais de poder.\nA participação ocorreria mediante convocação e em caráter\ngratuito. Jonas foi convocado com base nesse diploma normativo,\nmas se sentiu extremamente desconfortável em atuar, pois a\natividade a ser desenvolvida era francamente contrária à sua\nconvicção política.\nNa situação descrita, consoante a ordem constitucional, é correto\nafirmar que Jonas","options":{"A":"praticará crime inafiançável, se não cumprir a obrigação legal a todos imposta.","B":"não pode eximir-se, em nenhuma hipótese, de cumprir obrigação legal a todos imposta.","C":"estará em harmonia com a juridicidade caso cumpra prestação alternativa fixada em lei.","D":"somente pode deixar de cumprir a obrigação legal, por motivo de crença religiosa, se a lei for inconstitucional.","E":"somente pode eximir-se de cumprir obrigação legal a todos imposta por motivo de crença religiosa, o que não é o caso."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q38-p8-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-39","exam":"pcmg2025","number":39,"subject":"Direito Constitucional","text":"João, cientista político, ao analisar as características do Estado de\nDireito Alfa, constatou que se trata de unidade existencial que\napregoa uma concepção de máximo desenvolvimento material,\nainda que redunde em sacrifício da liberdade individual.\nAo analisar a referida característica à luz da finalidade do Estado,\nJoão concluiu corretamente que se está perante fins","options":{"A":"limitados.","B":"subjetivos.","C":"descritivos.","D":"expansivos.","E":"dogmáticos."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q39-p9-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-40","exam":"pcmg2025","number":40,"subject":"Direito Constitucional","text":"Foi identificada uma grave crise política no Município Beta,\nlocalizado no território do Estado Sigma e no qual está situado um\nimportante porto nacional, de grande relevância estratégica para\na exportação de determinado gênero alimentício.\nPor essa razão, diversas estruturas orgânicas federais se reuniram\ncom o objetivo de apresentar ao Presidente da República proposta\nde decretação de intervenção federal no referido município. Com\nisso, almejavam evitar possíveis impactos na balança comercial\nbrasileira.\nAo fim da reunião, concluiu-se corretamente que","options":{"A":"a decretação da intervenção pressupõe prévia autorização do Supremo Tribunal Federal.","B":"em razão do nível federativo no qual os fatos ocorreram, a União não pode decretar a intervenção.","C":"a intervenção pode ser decretada, considerando que a narrativa não descreve típico interesse local.","D":"a decretação da intervenção pressupõe requerimento nesse sentido do Chefe do Poder Executivo de Beta.","E":"a intervenção pode ser decretada pelo Presidente da República independentemente da provocação de outro órgão."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q40-p9-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-41","exam":"pcmg2025","number":41,"subject":"Direito Constitucional","text":"O Secretário de Administração Penitenciária do Estado Alfa,\nautoridade máxima do sistema penitenciário e do seu órgão\nadministrador, foi comunicado do início de uma rebelião na\nunidade prisional Kappa, no qual se encontravam os presos\nprovisórios da região norte do Estado. Em razão desses\nacontecimentos, a assessoria do Secretário constatou a\nnecessidade de ser reforçada a segurança no local, o que lhe foi\ndevidamente comunicado.\nÀ luz da sistemática constitucional, é correto afirmar que o\nSecretário","options":{"A":"pode determinar que a polícia penal ou a polícia militar realize a segurança do local.","B":"pode determinar que a polícia penal, vinculada que é à Secretaria, realize a segurança do local.","C":"deve requerer ao Governador do Estado que determine à polícia penal a realização da segurança do local.","D":"deve requerer ao Comandante Geral da Polícia Militar que determine o comparecimento de efetivo ao local.","E":"deve requerer ao Governador do Estado que determine a realização da segurança do local, o que pode ser feito pela polícia penal ou pela polícia militar."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q41-p9-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-42","exam":"pcmg2025","number":42,"subject":"Direito Constitucional","text":"A Lei Federal nº X, com o objetivo de exasperar o combate ao crime\norganizado, dispôs que o silêncio dos investigados que se\nencontrem presos provisoriamente pela prática da infração penal\nde organização criminosa, bem como pela prática de crimes\nconexos, seria interpretado em seu desfavor. Esse diploma\nnormativo, comemorado por alguns setores do ambiente\nsociopolítico, foi duramente criticado por outros.\nConsiderando os balizamentos estabelecidos pela ordem\nconstitucional, é correto afirmar que","options":{"A":"esse diploma normativo afronta o direito fundamental ao silêncio, de modo que a prova produzida com base na Lei Federal nº X é ilícita.","B":"a prova a ser obtida é lícita, na medida em que foi produzida em harmonia com a lei, logo, pode ser considerada pela autoridade competente.","C":"ainda que se trate de prova ilícita, pode ser considerada pela autoridade competente na medida em que se mostre relevante para a conclusão da investigação.","D":"a sistemática de combate às organizações criminosas não pode ser objeto de disciplina diferenciada, sob pena de afronta à isonomia, logo, a Lei Federal nº X é inconstitucional.","E":"o silêncio, enquanto projeção da personalidade individual, não é matéria afeta a padrões normativos, mas mera circunstância fática, que pode ser avaliada conforme a lei, logo, a Lei Federal nº X é constitucional."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q42-p9-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-43","exam":"pcmg2025","number":43,"subject":"Direito Penal","text":"Daniel, ao ter conhecimento de que um colega de trabalho foi\nvítima de determinado crime contra o patrimônio, ensejando\nelevado prejuízo financeiro, dirigiu-se a ele e, agindo com dolo,\nsolicitou, para si, a quantia de três salários mínimos, a pretexto de\ninfluir em ato praticado por policiais civis da Delegacia de Polícia\nda cidade, com o objetivo de agilizar as investigações. Disse, por\nfim, que os referidos agentes públicos eram seus amigos há anos e\nque atenderiam ao seu pleito.\nNesse cenário, considerando as disposições do Código Penal,\né correto afirmar que Daniel responderá pelo crime de","options":{"A":"advocacia administrativa.","B":"exploração de prestígio.","C":"tráfico de influência.","D":"corrupção passiva.","E":"corrupção ativa."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q43-p9-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-44","exam":"pcmg2025","number":44,"subject":"Direito Penal","text":"Após o encerramento da jornada de trabalho diária, Maria, maior\ne capaz, residente e domiciliada em Vespasiano/MG, ingressou em\num coletivo com destino à sua casa, sentando-se ao lado de Luís,\nque ela desconhecia.\nDurante o trajeto do ônibus, Maria percebeu que o agente estava\ntocando suas próprias partes íntimas, enquanto olhava,\nincessantemente, para ela. Diante do intenso incômodo, a vítima\npediu para que Luís interrompesse o comportamento em curso,\nmas ele deu continuidade à conduta, praticando ato libidinoso\ncom o objetivo de satisfazer a própria lascívia.\nNesse cenário, considerando as disposições do Código Penal, é\ncorreto afirmar que Luís responderá pelo crime de","options":{"A":"importunação sexual, com a incidência de uma causa de aumento de pena, já que a conduta ocorreu no interior de um transporte coletivo de passageiros.","B":"assédio sexual, com a incidência de uma causa de aumento de pena, já que a conduta ocorreu no interior de um transporte coletivo de passageiros.","C":"violação sexual mediante fraude, sem causas de aumento de pena.","D":"importunação sexual, sem causas de aumento de pena.","E":"assédio sexual, sem causas de aumento de pena."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q44-p10-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-45","exam":"pcmg2025","number":45,"subject":"Direito Penal","text":"Em janeiro de 2025, no Município de Viçosa/MG, Jonas se\naproximou de um transeunte e, mediante grave ameaça,\nconsubstanciada no emprego de uma faca, determinou a entrega\ndo seu telefone celular, sendo atendido. Em seguida, Jonas, na\nposse da res furtiva, correu, mas acabou sendo capturado em\nflagrante por um policial civil à paisana, três quarteirões depois.\nSendo assim, a vítima logrou recuperar o bem móvel que havia\nsido levado.\nNesse cenário, considerando as disposições do Código Penal, é\ncorreto afirmar que Jonas responderá pelo crime de","options":{"A":"extorsão tentada, sem a incidência de causas de aumento de pena, pois o emprego de arma branca deixou de ser majorante no referido delito.","B":"roubo tentado, sem a incidência de causas de aumento de pena, pois o emprego de arma branca deixou de ser majorante no referido delito.","C":"extorsão consumada, com a incidência da causa de aumento de pena atrelada ao emprego de arma branca.","D":"roubo tentado, com a incidência da causa de aumento de pena atrelada ao emprego de arma branca.","E":"roubo consumado, com a incidência da causa de aumento de pena atrelada ao emprego de arma branca."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q45-p10-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-46","exam":"pcmg2025","number":46,"subject":"Direito Penal","text":"Lucas, investigador de polícia, cumprindo ordens da autoridade\npolicial, compareceu ao imóvel de Matheus, localizado na cidade\nde Divinópolis/MG, com o objetivo de intimá-lo para ser ouvido\nem um inquérito policial em curso. Nesse contexto, ao tomar\nciência dos fatos, Matheus, irritado e agindo com dolo de lesionar,\ndesferiu dois socos no rosto de Lucas. Em razão da conduta\npraticada, o policial permaneceu afastado de suas funções por\numa semana.\nNesse cenário, considerando as disposições do Código Penal, é\ncorreto afirmar que Matheus responderá pelo crime de lesão\ncorporal","options":{"A":"simples, sendo certo que a pena será aumentada de um a dois terços, já que a conduta foi praticada contra policial civil, no exercício da função.","B":"culposa, sendo certo que o fato de a vítima ser policial civil, no exercício da função, não dá azo ao aumento da pena.","C":"simples, sendo certo que o fato de a vítima ser policial civil, no exercício da função, não dá azo ao aumento da pena.","D":"gravíssima, já que a conduta foi praticada contra policial civil, no exercício da função.","E":"grave, já que a conduta foi praticada contra policial civil, no exercício da função."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q46-p10-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-47","exam":"pcmg2025","number":47,"subject":"Direito Penal","text":"João, servidor público do Município de Belo Horizonte/MG, agindo\ncom dolo, compareceu a uma delegacia de polícia, afirmando que\nLucas, colega de repartição pública, estaria desviando bens\npúblicos em proveito próprio. Registre-se que João tinha\nconhecimento da inocência de Lucas, mas agiu para prejudicá-lo.\nInstaurado um inquérito policial para apurar os fatos, constatou-\nse que as alegações eram falsas.\nNesse cenário, considerando as disposições do Código Penal, é\ncorreto afirmar que João responderá pelo crime de","options":{"A":"comunicação falsa de crime, na modalidade qualificada, por envolver alegação de prática de crime contra a Administração Pública.","B":"denunciação caluniosa, na modalidade qualificada, por envolver alegação de prática de crime contra a Administração Pública.","C":"falso testemunho, na modalidade qualificada, por envolver alegação de prática de crime contra a Administração Pública.","D":"comunicação falsa de crime, na modalidade simples.","E":"denunciação caluniosa, na modalidade simples."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q47-p10-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-48","exam":"pcmg2025","number":48,"subject":"Direito Processual Penal","text":"Encerrado o curso de formação na Academia de Polícia, João foi\ndesignado para atuar, na qualidade de plantonista, no norte do\nEstado de Minas Gerais. Nesse contexto, logo no início do primeiro\nplantão do referido agente público, a Polícia Militar encaminhou\nCaio, capturado em flagrante, à Delegacia de Polícia.\nDe acordo com a narrativa, avalie as afirmativas a seguir.\nI.\nApresentado o preso à autoridade competente, esta ouvirá o\ncondutor e colherá, desde logo, sua assinatura, entregando-\nlhe a cópia do termo e o recibo de entrega do preso. Em\nseguida, procederá à oitiva das testemunhas que o\nacompanharem e ao interrogatório do acusado sobre a\nimputação que lhe é feita, colhendo, após cada oitiva, suas\nrespectivas assinaturas, lavrando, a autoridade, afinal, o auto.\nII. A prisão de qualquer pessoa e o local onde se encontra serão\ncomunicados, em até 24 horas, ao Ministério Público e à\nfamília do preso ou à pessoa por ele indicada.\nIII. Em até 48 horas após a realização da prisão, será encaminhado\nao Juiz competente o auto de prisão em flagrante e, caso o\nautuado não informe o nome de seu(sua) advogado(a), a cópia\nintegral para a Defensoria Pública.\nConsiderando as disposições do Código de Processo Penal, está\ncorreto o que se afirma em","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e III, apenas.","E":"I, II e III."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q48-p11-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-49","exam":"pcmg2025","number":49,"subject":"Direito Processual Penal","text":"João, agindo com dolo, efetuou disparos de arma de fogo em\nBruno, seu desafeto, o qual, imediatamente, faleceu, ensejando\nforte repercussão social na municipalidade.\nAssim que tiver conhecimento da infração penal, a autoridade\npolicial pode, com base no Código de Processo Penal, assumir os\nprocedimentos a seguir, à exceção de um. Assinale-o.","options":{"A":"Deverá colher informações sobre a existência de filhos, respectivas idades, se possuem alguma deficiência e o nome e o contato de eventual responsável pelos cuidados dos filhos, indicados pela pessoa presa.","B":"Deverá dirigir-se ao local, providenciando para que não se alterem o estado e a conservação das coisas, até a chegada dos peritos criminais.","C":"Deverá apreender os objetos que tiverem relação com o fato, após liberados pelos investigadores de polícia.","D":"Deverá determinar, se for o caso, que se proceda a exame de corpo de delito e a quaisquer outras perícias.","E":"Deverá colher todas as provas que servirem para o esclarecimento do fato e suas circunstâncias."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q49-p11-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-50","exam":"pcmg2025","number":50,"subject":"Direito Processual Penal","text":"Jonas, recém-empossado no cargo de investigador de polícia,\ndurante o curso de formação realizado na Academia de Polícia,\nparticipou de diversas palestras que tinham o inquérito policial\ncomo tema.\nNesse cenário, considerando as disposições do Código de Processo\nPenal, avalie as afirmativas a seguir e assinale (V) para a verdadeira\ne (F) para a falsa.\n(   ) Depois de ordenado o arquivamento do inquérito pela\nautoridade judiciária, por falta de base para a denúncia, a\nautoridade policial não poderá proceder a novas pesquisas,\ninclusive se tiver notícia de outras provas.\n(   ) O Ministério Público não poderá requerer a devolução do\ninquérito à autoridade policial, senão para novas diligências,\nimprescindíveis ao oferecimento da denúncia.\n(   ) A autoridade policial não poderá mandar arquivar os autos de\ninquérito.\nAs afirmativas são, respectivamente,","options":{"A":"V – F – V.","B":"F – V – F.","C":"V – V – F.","D":"V – V – V.","E":"F – V – V."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q50-p11-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-51","exam":"pcmg2025","number":51,"subject":"Direito Processual Penal","text":"O direito de representação no contexto da ação penal, de acordo\ncom o Código de Processo Penal, poderá ser exercido,\npessoalmente ou por procurador, com poderes especiais.\nEm relação ao tema, avalie as afirmativas a seguir.\nI.\nSe com a representação forem oferecidos elementos que\nhabilitem o Ministério Público a promover a ação penal, o\nórgão ministerial solicitará que o inquérito policial seja\nconcluído no prazo de 15 dias, findo o qual oferecerá denúncia.\nII. Oferecida ou reduzida a termo a representação, a autoridade\npolicial procederá a inquérito, ou, não sendo competente,\nremetê-lo-á à autoridade que o for.\nIII. A representação conterá todas as informações que possam\nservir à apuração do fato e da autoria.\nConsiderando as disposições do Código de Processo Penal, está\ncorreto o que se afirma em","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q51-p11-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-52","exam":"pcmg2025","number":52,"subject":"Direito Processual Penal","text":"Acerca da teoria geral da prova, segundo o Código de Processo\nPenal, avalie as afirmativas a seguir.\nI.\nO Juiz formará sua convicção pela livre apreciação da prova\nproduzida\nem\ncontraditório\njudicial,\nnão\npodendo\nfundamentar sua decisão exclusivamente nos elementos\ninformativos colhidos na investigação, ressalvadas as provas\ncautelares, não repetíveis e antecipadas.\nII. São inadmissíveis, devendo ser desentranhadas do processo,\nas provas ilícitas, assim entendidas aquelas obtidas em\nviolação a normas constitucionais ou legais.\nIII. Preclusa a decisão de desentranhamento da prova declarada\ninadmissível, esta será inutilizada por decisão judicial,\nfacultado às partes acompanhar o incidente.\nEstá correto o que se afirma em","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q52-p12-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-53","exam":"pcmg2025","number":53,"subject":"Legislação Extravagante","text":"Após ser agredida, física e verbalmente, por seu companheiro,\nMaria, rompendo com o ciclo de violência existente, resolve se\nencaminhar à Delegacia de Polícia, onde pretende narrar o\nocorrido.\nConsiderando as disposições da Lei nº 11.340/2006, avalie se a\ninquirição de Maria deve seguir as diretrizes abaixo:\nI.\nA garantia de que, em nenhuma hipótese, ela terá contato\ndireto com investigados ou suspeitos ou com pessoas a eles\nrelacionadas.\nII. A não revitimização da depoente, evitando sucessivas\ninquirições sobre o mesmo fato nos âmbitos criminal, cível e\nadministrativo, bem como questionamentos sobre a vida\nprivada.\nIII. A salvaguarda da integridade física, psíquica e emocional da\ndepoente, considerada a sua condição peculiar de pessoa em\nsituação de violência doméstica e familiar.\nEstá correto o que se afirma em","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q53-p12-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-54","exam":"pcmg2025","number":54,"subject":"Legislação Extravagante","text":"Fábio, reincidente em crime doloso, cumpre pena definitiva, em\nregime fechado, pela prática do crime de roubo circunstanciado\npelo emprego de arma de fogo. No curso da execução penal,\nsobrevém o falecimento do cônjuge do apenado.\nNesse cenário, considerando as disposições da Lei de Execução\nPenal, é correto afirmar que Fábio","options":{"A":"tem direito à permissão de saída, que será concedida pelo diretor do estabelecimento onde se encontra preso.","B":"tem direito à saída temporária, que será concedida pelo diretor do estabelecimento onde se encontra preso.","C":"tem direito à saída temporária, mediante escolta, perdurando pelo tempo necessário à finalidade da saída.","D":"não tem direito à permissão de saída, por estar cumprindo pena em regime fechado.","E":"não tem direito à permissão de saída, por ser reincidente em crime doloso."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q54-p12-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-55","exam":"pcmg2025","number":55,"subject":"Legislação Extravagante","text":"Após ser capturado em flagrante com 500 pinos de cocaína, em\nlocal dominado pelo tráfico de drogas, Mário foi encaminhado, por\npoliciais militares, à Delegacia de Polícia de plantão.\nSobre a hipótese narrada, considerando as disposições da\nLei nº 11.343/2006, avalie as afirmativas a seguir e assinale (V)\npara a verdadeira e (F) para a falsa.\n(   ) Para efeito da lavratura do auto de prisão em flagrante e do\nestabelecimento da materialidade do delito, é suficiente o\nlaudo de constatação da natureza e quantidade da droga,\nfirmado por perito oficial ou, na falta deste, por duas pessoas\nidôneas.\n(   ) Recebida a cópia do auto de prisão em flagrante, o Juiz, no\nprazo de dez dias, certificará a regularidade formal do laudo de\nconstatação e determinará a destruição das drogas\napreendidas, guardando-se amostra necessária à realização do\nlaudo definitivo.\n(   ) A destruição das drogas será executada pelo Delegado de\nPolícia competente no prazo de 30 dias na presença do Juiz, do\nMinistério Público e da autoridade sanitária.\nAs afirmativas são, respectivamente,","options":{"A":"V – F – V.","B":"V – V – V.","C":"F – V – F.","D":"F – F – F.","E":"F – V – V."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q55-p12-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-56","exam":"pcmg2025","number":56,"subject":"Legislação Extravagante","text":"De acordo com a Lei nº 12.850/2013, a infiltração de agentes de\npolícia em tarefas de investigação, representada pelo Delegado de\nPolícia ou requerida pelo Ministério Público, após manifestação\ntécnica do Delegado de Polícia quando solicitada no curso de\ninquérito policial, será precedida de circunstanciada, motivada e\nsigilosa\nautorização\njudicial,\nque\nestabelecerá\nseus limites.\nDe acordo com a narrativa e considerando as disposições da\nLei nº 12.850/2013, avalie as afirmativas a seguir.\nI.\nNo curso do inquérito policial, o Delegado de Polícia poderá\ndeterminar aos seus agentes, e o Ministério Público poderá\nrequisitar, a qualquer tempo, relatório da atividade de\ninfiltração.\nII. A infiltração será autorizada pelo prazo de seis meses,\nprorrogável uma única vez, por igual período, desde que\ncomprovada sua necessidade.\nIII. Na hipótese de representação do Delegado de Polícia, o Juiz\ncompetente, antes de decidir, ouvirá o Ministério Público.\nEstá correto o que se afirme em","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"I e III, apenas.","D":"II e III, apenas.","E":"I, II e III."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q56-p13-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-57","exam":"pcmg2025","number":57,"subject":"Direitos Humanos","text":"Assinale a opção que apresenta corretamente uma característica\ndos Direitos Humanos, aqueles direitos essenciais e indispensáveis\nà vida digna.","options":{"A":"Renunciabilidade, pois o titular do direito pode abdicar do seu exercício.","B":"Alienabilidade, uma vez que podem ser objetos de ação indenizatória, quando violados.","C":"Essencialidade, em razão de serem essenciais por natureza, do ponto de vista material e formal.","D":"Prescritibilidade, posto que devem ser exercidos em um determinado período, sob pena de preclusão.","E":"Dependência, uma vez que são direitos autônomos, que são exercidos de forma independente, um dos outros."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q57-p13-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-58","exam":"pcmg2025","number":58,"subject":"Direitos Humanos","text":"O Estado Brasileiro integra o Sistema Interamericano de Direitos\nHumanos.\nNesse contexto, assinale a afirmativa correta.","options":{"A":"O Sistema interamericano de Direitos Humanos é composto pela Comissão Interamericana de Direitos Humanos e pela Corte Internacional de Justiça.","B":"A Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância foi incorporada pelo Brasil com status de emenda constitucional.","C":"A sentença do Caso Favela Nova Brasília para ser válida, precisa ser homologada pelo Superior Tribunal de Justiça, conforme o rito das sentenças estrangeiras.","D":"A Declaração Americana de Direitos Humanos é o instrumento normativo fundamental da Organização dos Estados Americanos.","E":"O sistema interamericano pode ser acionado por qualquer cidadão, que tenha um direito humano violado, que sempre terá seu caso diretamente julgado pela Corte DH."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q58-p13-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-59","exam":"pcmg2025","number":59,"subject":"Direitos Humanos","text":"O Estado Brasileiro faz parte do Sistema Global de Proteção dos\nDireitos Humanos, decorrente da Organização das Nações Unidas\n(ONU).\nSobre este assunto, assinale a afirmativa correta.","options":{"A":"A Declaração Universal dos Direitos Humanos é norma jurídica de observância obrigatória por todos os Estados que a ratificaram.","B":"O Pacto Internacional sobre direitos civis e políticos foi incorporado automaticamente no âmbito interno do Brasil, com a sua ratificação perante a ONU.","C":"O Caso Alyne Pimentel é um caso de condenação do Brasil sobre morte materna proferida pelo Comitê pela Eliminação de Todas as Formas de Discriminação contra a Mulher.","D":"Com a criação das Nações Unidas, os Estados integrantes do Sistema ONU se obrigaram a observar os Direitos Humanos previstos nos tratados aprovados por aquele colegiado.","E":"A Convenção sobre os direitos da Criança é um exemplo de normativa que foi ratificada, sem ressalvas, por todos os Estados-membros da ONU."},"key":null,"annulled":true,"originalImages":["../assets/questions/pcmg-2025-q59-p13-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Questão oficialmente anulada; não entra no aproveitamento."},{"id":"pcmg2025-60","exam":"pcmg2025","number":60,"subject":"Direitos Humanos","text":"A Emenda Constitucional nº 45/2004 aprimorou as regras de\ninternalização dos tratados internacionais sobre Direitos\nHumanos.\nSobre essa temática, avalie as afirmativas a seguir e assinale (V)\npara a verdadeira e (F) para a falsa.\n(   ) Prevalece o entendimento do Supremo Tribunal Federal de\nque, após o advento da EC nº 45/2004, todos os tratados de\nDireitos Humanos têm natureza de norma constitucional.\n(   ) Os tratados e convenções internacionais sobre Direitos\nHumanos que forem aprovados, em cada Casa do Congresso\nNacional, em dois turnos, por três quintos dos votos dos\nrespectivos membros, serão equivalentes às emendas\nconstitucionais.\n(   ) Os tratados e convenções de Direitos Humanos ratificados\npelo Brasil não precisam ser aprovados pelo Congresso\nNacional, tendo em vista o disposto no Art. 5º, § 1º, da\nConstituição Federal.\nAs afirmativas são, respectivamente,","options":{"A":"F – V – F.","B":"F – F – V.","C":"F – F – F.","D":"V – V – F.","E":"V – F – V."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q60-p13-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-61","exam":"pcmg2025","number":61,"subject":"Medicina Legal","text":"Sobre perícia, como o conjunto de procedimentos técnicos que\ntem como finalidade o esclarecimento de um fato à Justiça,\nassinale a afirmativa correta.","options":{"A":"O laudo pericial sempre será um documento sigiloso.","B":"A perícia não pode ser negada às partes pelo Juiz ou autoridade policial.","C":"O Juiz não ficará adstrito ao laudo, podendo rejeitá-lo no todo ou em partes.","D":"A perícia pode ser substituída pela confissão do acusado, mesmo quando a infração deixar vestígios.","E":"A perícia é um ato de instrução exclusivo da fase de inquérito policial, não podendo ser realizada na fase processual penal."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q61-p14-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-62","exam":"pcmg2025","number":62,"subject":"Medicina Legal","text":"Relacione as etapas do rastreamento do vestígio que compõem a\ncadeia de custódia, listadas a seguir, às respectivas características.\n1. Fixação\n2. Isolamento\n3. Reconhecimento\n4. Descarte\n5. Processamento\n(   ) Ato de distinguir um elemento como de potencial interesse\npara a produção da prova pericial.\n(   ) Descrição detalhada do vestígio, como foi encontrado na cena\ndo crime.\n(   ) Ato pericial propriamente dito, manipulação do vestígio e\nconfecção do laudo.\n(   ) Ato de evitar que se altere o estado das coisas, preservando o\nambiente imediato, mediato e relacionado aos vestígios do\nlocal de crime.\n(   ) Liberação do vestígio mediante autorização judicial.\nAssinale a opção que apresenta a relação correta, segundo a\nordem apresentada.","options":{"A":"1 – 3 – 4 – 5 – 2.","B":"2 – 1 – 5 – 3 – 4.","C":"2 – 5 – 1 – 4 – 3.","D":"3 – 1 – 5 – 2 – 4.","E":"3 – 2 – 1 – 5 – 4."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q62-p14-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-63","exam":"pcmg2025","number":63,"subject":"Medicina Legal","text":"Sobre a identificação humana, assinale a afirmativa incorreta.","options":{"A":"O exame de DNA é sempre a melhor opção para a identificação de remanescentes humanos.","B":"O exame odontológico para identificação depende do confronto de informações ante mortem e post mortem.","C":"Os ossos do crânio e da pelve permitem a estimativa do sexo do indivíduo por métodos não métricos ou morfológicos.","D":"A primeira fase da identificação necropapiloscópica busca coincidências entre as figuras delta, arco, presilhas externa e interna e verticilo.","E":"São necessários doze pontos coincidentes e nenhum excludente para a comprovação da identificação necropapiloscópica."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q63-p14-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-64","exam":"pcmg2025","number":64,"subject":"Medicina Legal","text":"Os elementos da balística terminal são importantes para estimar a\ndistância entre a vítima e o atirador.\nSobre o anel de Fisch, assinale a afirmativa correta.","options":{"A":"Só existe em disparos a curta distância.","B":"Corresponde aos orifícios de saída de arma longa.","C":"É formado por orla de equimose, escoriação e enxugo.","D":"Está presente em orifícios de entrada com cano encostado.","E":"É formado por zonas de tatuagem, queimadura e esfumaçamento."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q64-p14-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-65","exam":"pcmg2025","number":65,"subject":"Medicina Legal","text":"A tanatologia forense estuda, por meio da cronotanatognose, a\nsequência de fenômenos cadavéricos para determinação da hora\nda morte.\nSobre esse período, assinale a afirmativa correta.","options":{"A":"O resfriamento é o primeiro sinal de morte.","B":"A putrefação tem início após 48 horas de morte.","C":"A rigidez cadavérica é o primeiro sinal de certeza de morte.","D":"A rigidez cadavérica e a putrefação são sinais precoces de morte.","E":"O período de incerteza corresponde às primeiras seis horas após a morte."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q65-p14-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-66","exam":"pcmg2025","number":66,"subject":"Criminologia","text":"O fenômeno criminológico que se refere à estatística de crimes\ncometidos por funcionários públicos contra vítimas que não\ndenunciam o fato por temor de represálias é denominado:","options":{"A":"Cifra negra.","B":"Cifra amarela.","C":"Cifra dourada.","D":"Cifra verde.","E":"Cifra cinza."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q66-p14-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-67","exam":"pcmg2025","number":67,"subject":"Criminologia","text":"No que se refere às Escolas da Criminologia, assinale a afirmativa\ncorreta.","options":{"A":"A Escola Clássica da Criminologia tinha como principal expoente Cesare Lombroso.","B":"A Escola da Criminologia Crítica tem como principal objeto de estudo o delinquente.","C":"A Criminologia Radical rechaça a metodologia interdisciplinar.","D":"A Teoria do Etiquetamento Penal preconiza a noção de atavismo.","E":"A Escola da Criminologia Positivista baseia-se no paradigma etiológico."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q67-p14-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-68","exam":"pcmg2025","number":68,"subject":"Criminologia","text":"Pierri participou de um congresso sobre Criminologia. Nos grupos\nde trabalho, algumas apresentações de estudantes lhe chamaram\na atenção.\nSão elas:\nI.\n“O discurso Tolerância Zero surgiu a partir da política de\nsegurança pública implementada na Colômbia a partir de\n1994.”\nII. “O Direito Penal do Inimigo é a teoria cunhada pelo jurista\nalemão Claus Roxin que preconiza dois direitos penais.”\nIII. “A Política Criminal Atuarial se baseia em análises\nquantitativas e previsões estatísticas com foco na prevenção\ndo delito.”\nIV. “O Direito Penal Mínimo defende a limitação do poder\npunitivo com\nrespeito aos direitos e às garantias\nfundamentais.”\nAnalisando o conteúdo acima descrito, conclui-se que está correto\no que se afirma em","options":{"A":"I, III e IV.","B":"II, III e IV.","C":"I, II e III.","D":"IV, apenas.","E":"III e IV, apenas."},"key":"E","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q68-p15-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa E. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-69","exam":"pcmg2025","number":69,"subject":"Criminologia","text":"Com relação aos modelos de prevenção ao delito, assinale a\nafirmativa correta.","options":{"A":"A implementação de políticas públicas de saúde, de educação e de saneamento básico é compreendida como prevenção secundária ao delito.","B":"Entende-se por prevenção primária o monitoramento de grupos sociais mais propensos à prática delitiva.","C":"A prevenção terciária pretende evitar a reincidência criminal por meio de políticas voltadas à ressocialização do apenado.","D":"O modelo de prevenção integral ou integrada preconiza a redução da criminalidade apenas por meio de políticas criminais.","E":"Os programas de prevenção primária e secundária devem ser implementados pelas instituições policiais."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q69-p15-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2025-70","exam":"pcmg2025","number":70,"subject":"Criminologia","text":"Acerca do conceito de Criminologia e saberes penais afins,\nrelacione os enunciados aos respectivos termos.\nI.\nEstudo empírico e interdisciplinar que se propõe a explicar as\ncausas da criminalidade.\nII. Se refere ao conjunto de medidas e programas governamentais\nvoltados à prevenção e à repressão do delito.\nIII. Compreende o arcabouço de normas e princípios que\nestabelecem os crimes e suas respectivas sanções.\n(   ) Dogmática Penal\n(   ) Política Criminal\n(   ) Criminologia\nAssinale a opção que indica a relação correta, na ordem\napresentada.","options":{"A":"III – II – I.","B":"III – I – II.","C":"II – III – I.","D":"II – I – III.","E":"I – II – III."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2025-q70-p15-1.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-1","exam":"pcmg2021","number":1,"subject":"Português","text":"“muitas pessoas demonstram não ter uma cultura de valores inserida em sua vida”.\nUm dos argumentos que sustentam a afirmativa inicial do autor é:","options":{"A":" A condição de trabalho do policial.","B":" A escassez de valores de afeto.","C":" A garantia dos direitos do povo.","D":" Os princípios das relações sociais."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q1-p4-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto01-p3-0.webp","../assets/questions/pcmg-2021-texto01-p4-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-2","exam":"pcmg2021","number":2,"subject":"Português","text":"“O mundo físico e social se complicou muito; todavia, o homem não vive isolado\nou num mundo só material, mas, sim, num mundo de convivência, cujos valores\nprecisam ser conhecidos, compreendidos e postos em prática.”\nSobre a pontuação do período acima, NÃO é correto afirmar:","options":{"A":" A conjunção adverbial “e” elimina a vírgula pela presença da enumeração.","B":" A palavra “sim” está entre vírgulas para enfatizar o ponto de vista do autor.","C":" A vírgula antes do pronome relativo “cujos” antecede uma oração adjetiva.","D":" O ponto e vírgula foi empregado para marcar um contraste entre as orações."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q2-p4-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto01-p3-0.webp","../assets/questions/pcmg-2021-texto01-p4-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-3","exam":"pcmg2021","number":3,"subject":"Português","text":"A alternativa que demonstra como a sociedade em geral pode contribuir para que\no profissional da segurança pública possa executar de forma adequada a sua fun-\nção é:","options":{"A":" A defesa dos direitos do cidadão.","B":" A ética profissional.","C":" A responsabilidade e competência policial.","D":" O reconhecimento de valores."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q3-p5-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto01-p3-0.webp","../assets/questions/pcmg-2021-texto01-p4-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-4","exam":"pcmg2021","number":4,"subject":"Português","text":"O uso de aspas na palavra “deseducação” indica","options":{"A":" citação.","B":" estrangeirismo.","C":" neologismo.","D":" paráfrase."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q4-p5-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto01-p3-0.webp","../assets/questions/pcmg-2021-texto01-p4-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-5","exam":"pcmg2021","number":5,"subject":"Português","text":"Sobre as características da Redação Oficial, relacione a 2ª coluna de acordo com\na 1ª.\n(1) Objetividade\n(   )\nEscolha de expressão ou palavra que não con-\nfira duplo sentido ao texto\n(2) Impessoalidade\n(   )\nA transparência é requisito do próprio Estado de\nDireito\n(3) Concisão\n(   )\nIr diretamente ao assunto que se deseja abor-\ndar, sem voltas e sem redundâncias\n(4) Clareza\n(   )\nTransmitir o máximo de informações com o mí-\nnimo de palavras\n(5) Precisão\n(   )\nSer isenta da interferência da individualidade de\nquem a elabora\nA sequência CORRETA, de cima para baixo, é:","options":{"A":" 4, 2, 1, 3, 5.","B":" 3, 2, 5, 1, 4.","C":" 1, 5, 4, 2, 3.","D":" 5, 4, 1, 3, 2."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q5-p5-0.webp","../assets/questions/pcmg-2021-q5-p6-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto01-p3-0.webp","../assets/questions/pcmg-2021-texto01-p4-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-6","exam":"pcmg2021","number":6,"subject":"Português","text":"No Texto 02, NÃO se identifica o uso de vírgulas para","options":{"A":" isolar expressões explicativas.","B":" isolar o aposto do termo principal.","C":" separar oração adverbial, quando anteposta à principal.","D":" separar oração coordenada sindética."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q6-p6-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto02-p6-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-7","exam":"pcmg2021","number":7,"subject":"Português","text":"“Nosso homenzinho teria toda razão para rolar pelo chão e dar gargalhadas por\ntodas as bocas.\nSobre a articulação das orações do período acima, é CORRETO afirmar:","options":{"A":" A oração principal é “Nosso homenzinho teria toda razão”.","B":" A última oração é coordenada aditiva.","C":" Contém uma oração subordinada reduzida adverbial final.","D":" É composto por 4 (quatro) orações."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q7-p7-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto02-p6-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-8","exam":"pcmg2021","number":8,"subject":"Português","text":"Qual das funções da palavra “se” é identificada no Texto 02?","options":{"A":" Conjunção subordinativa condicional.","B":" Objeto indireto.","C":" Palavra expletiva ou de realce.","D":" Substantivo."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q8-p7-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto02-p6-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-9","exam":"pcmg2021","number":9,"subject":"Português","text":"NÃO há oração subordinada adjetiva em:","options":{"A":" A Unidade de Saúde onde atendo foi assaltada na tarde de ontem.","B":" Alcançará o sucesso, ainda que todos duvidem de sua capacidade de tra- balho.","C":" As lojas em que procuramos os presentes de Natal tinham preços altíssi- mos.","D":" Os alunos, que têm dificuldade em matemática, terão aulas à noite."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q9-p7-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto02-p6-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-10","exam":"pcmg2021","number":10,"subject":"Português","text":"Analise as afirmativas sobre a coerência e a coesão textual, identificando-as com\n(V) ou (F) conforme sejam verdadeiras ou falsas.\n(   )\nCoesão é articulação gramatical existente entre as palavras de um texto,\nde forma a garantir a conexão sequencial.\n(   )\nCoerência é o resultado da articulação das ideias de um texto, que apon-\ntam para uma unidade de sentido.\n(   )\nUm texto coerente não contém contradições e suas partes constituem um\ntodo significativo.\n(   )\nConjunções e preposições contribuem para ligação coesiva entre elemen-\ntos linguísticos: palavras, orações e períodos.\nA sequência CORRETA, de cima para baixo, é:","options":{"A":" F, F, F, F.","B":" F, V, F, V.","C":" V, V, F, F.","D":" V, V, V, V."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q10-p8-0.webp"],"supportImages":["../assets/questions/pcmg-2021-texto02-p6-0.webp"],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-11","exam":"pcmg2021","number":11,"subject":"Lei Orgânica da PCMG","text":"Quanto à estrutura orgânica da PCMG, definida no art. 17 da Lei Complementar\nn.º 129/2013, é CORRETO afirmar:","options":{"A":" O Instituto de Criminalística e o Instituto Médico-Legal subordinam-se à Superintendência de Informações e Inteligência Policial.","B":" O Instituto de Criminologia e o Colégio Ordem e Progresso subordinam-se ao Departamento de Trânsito de Minas Gerais.","C":" O Instituto de Identificação subordina-se à Superintendência de Polícia Técnico-Científica.","D":" Os Departamentos de Polícia Civil, a Divisão de Polícia Interestadual e a Casa de Custódia da Polícia Civil subordinam-se à Superintendência de Investigação e Polícia Judiciária."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q11-p8-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-12","exam":"pcmg2021","number":12,"subject":"Lei Orgânica da PCMG","text":"Sobre a penalidade de suspensão, prevista na Lei n.º 5.406/1969, e seus efeitos,\né INCORRETO afirmar:","options":{"A":" A autoridade que aplicar a pena de suspensão não poderá convertê-la em multa.","B":" A pena de suspensão não excederá noventa dias.","C":" A pena de suspensão será aplicada no caso da falta grave ou de reincidência.","D":" O servidor policial suspenso perderá todas as vantagens e direitos decorrentes do exercício do cargo."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q12-p9-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-13","exam":"pcmg2021","number":13,"subject":"Lei Orgânica da PCMG","text":"No que tange à penalidade de demissão, prevista na Lei n.º 5.406/1969, é INCOR-\nRETO afirmar:","options":{"A":" A pena de demissão por ineficiência no serviço será aplicada mesmo quando verificada a possibilidade de readaptação.","B":" A pena de demissão será aplicada nos casos de ausência ao serviço, sem causa justificável, por mais de quarenta e cinco dias, interpoladamente, durante um ano.","C":" A pena de demissão será aplicada nos casos de exercício de qualquer atividade remunerada, estando o servidor licenciado para tratamento de saúde.","D":" A pena de demissão será aplicada nos casos de procedimento irregular de natureza grave."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q13-p9-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-14","exam":"pcmg2021","number":14,"subject":"Lei Orgânica da PCMG","text":"De acordo com o disposto no art. 16 da Lei Complementar n.º 129/2013, compete\nà PCMG o exercício das seguintes atribuições, EXCETO:","options":{"A":" Desenvolver atividades de ensino, extensão e pesquisa, em caráter permanente, objetivando o aprimoramento de suas competências institucionais.","B":" Formalizar o inquérito policial e o termo circunstanciado de ocorrência, vedada a instauração do procedimento para apuração de ato infracional.","C":" Organizar e executar as atividades de registro, controle e licenciamento de veículos automotores, a formação e habilitação de condutores, o serviço de estatística, a educação de trânsito e o julgamento de recursos administrativos.","D":" Realizar correições e inspeções, em caráter permanente ou extraordinário, em atividades e em repartições em que atue, bem como responsabilizar-se pelos procedimentos disciplinares destinados a apurar eventual prática de infrações atribuídas a seus servidores."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q14-p9-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-15","exam":"pcmg2021","number":15,"subject":"Lei Orgânica da PCMG","text":"Compete ao Conselho Superior da PCMG, conforme o previsto no art. 26 da Lei\nComplementar n.º 129/2013, EXCETO:","options":{"A":" Estudar e propor inovações, visando à eficiência da atividade policial civil.","B":" Examinar e subsidiar a formulação da proposta orçamentária da PCMG, propor a priorização de programas, projetos e ações da PCMG e acompanhar a execução do orçamento da PCMG.","C":" Outorgar a Medalha do Mérito Policial Civil Delegado Luiz Soares de Souza Rocha, criada pela Lei nº 7.920, de 8 de janeiro de 1981, e demais condecorações e distinções honoríficas.","D":" Promover a movimentação de servidores, proporcionando equilíbrio entre os órgãos e unidades da PCMG, observado o quadro de distribuição de pessoal, nos termos de regulamento."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q15-p10-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-16","exam":"pcmg2021","number":16,"subject":"Lei Orgânica da PCMG","text":"Compete à Superintendência de Informações e Inteligência Policial, conforme pre-\nvisão do art. 39 da Lei Complementar n.º 129/2013, EXCETO:","options":{"A":" Dirigir as atividades de estatística, telecomunicações e informática no âmbito da PCMG.","B":" Disponibilizar para os Delegados de Polícia informações que possam subsidiar investigações criminais.","C":" Organizar e manter biblioteca especializada em matéria de interesse dos serviços policiais civis.","D":" Ter acesso a dados oriundos do serviço de identificação civil e criminal, de registro de veículos e cadastro de condutores, para fins notariais e de composição das informações relevantes para os atos de investigação criminal e de polícia judiciária."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q16-p10-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-17","exam":"pcmg2021","number":17,"subject":"Lei Orgânica da PCMG","text":"Sobre indenizações e gratificações previstas na Lei Complementar n.º 129/2013,\né INCORRETO afirmar:","options":{"A":" Ao policial civil da ativa será assegurado pelo Estado, a título de indenização para aquisição de vestimenta necessária ao desempenho de suas funções, o valor correspondente a 40% (quarenta por cento) do vencimento básico do nível I da carreira de Investigador de Polícia, a ser pago anualmente no mês de abril.","B":" Aos integrantes das carreiras da PCMG será atribuída gratificação por encargo de curso ou concurso, por hora-aula proferida em cursos, inclusive para atuação em bancas examinadoras, em processo de habilitação, controle e reabilitação de condutor de veículo automotor, de competência da Academia de Polícia Civil ou do Detran-MG, nos termos de decreto.","C":" O policial civil da ativa fará jus a auxílio-moradia.","D":" Salvo por imposição legal, ordem judicial ou autorização do servidor, nenhum desconto incidirá sobre os vencimentos, proventos ou pensão."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q17-p11-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-18","exam":"pcmg2021","number":18,"subject":"Lei Orgânica da PCMG","text":"São atribuições do cargo de Investigador de Polícia, EXCETO:","options":{"A":" Colher as impressões digitais para fins de identificação civil e criminal, inclusive de cadáveres, para a realização do exame datiloscópico.","B":" Cumprir e formalizar diligências policiais, mandados e outras determinações do Delegado de Polícia competente, analisar, pesquisar, classificar e processar dados e informações para a obtenção de vestígios e indícios probatórios relacionados a infrações penais e administrativas.","C":" Obter elementos para a identificação antropológica de pessoas, no que se refere às características sociais e culturais que compõem a vida pregressa e o perfil do submetido à investigação criminal.","D":" Registrar em termo declarações, depoimentos e informações de autores, suspeitos, vítimas, testemunhas, adolescente infrator e demais pessoas envolvidas nos procedimentos de polícia judiciária, mediante inquirição do Delegado de Polícia competente, cooperando na formulação das perguntas a serem respondidas."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q18-p11-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-19","exam":"pcmg2021","number":19,"subject":"Lei Orgânica da PCMG","text":"No que tange ao regime do trabalho do policial civil, é CORRETO afirmar:","options":{"A":" A prestação de serviço em regime de plantão implica no descanso, imediato e subsequente, pelo período mínimo de setenta e duas horas.","B":" O período em trânsito para a realização de diligências policiais em localidade diversa da lotação do policial civil, em qualquer região do Estado ou fora dele, não é considerado como tempo efetivamente trabalhado.","C":" O regime do trabalho policial civil se caracteriza pela prestação de serviço em condições adversas de segurança, cumprimento de jornadas normais e excepcionais, sujeito a plantões noturnos e a convocações a qualquer hora e dia, inclusive durante o repouso semanal e férias, garantidas, em caso de se exceder a carga horária prevista em lei, as compensações devidas.","D":" O regime do trabalho policial civil se caracteriza pela realização de diligências policiais em qualquer região do Estado, mas não fora dele."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q19-p12-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-20","exam":"pcmg2021","number":20,"subject":"Lei Orgânica da PCMG","text":"Em relação à disciplina do procedimento administrativo, estabelecida pela Lei n.º\n5.406/1969, é INCORRETO afirmar:","options":{"A":" O procedimento administrativo para apuração das transgressões disciplinares dos servidores da Polícia Civil compreende a sindicância administrativa e o processo administrativo.","B":" O processo será precedido de sindicância, quando não houver elementos suficientes para se concluir pela existência da falta ou de sua autoria.","C":" Os Chefes de Departamentos são competentes para determinar a instauração do processo administrativo.","D":" Será obrigatório o processo administrativo quando a falta disciplinar, por sua natureza, possa determinar a pena de demissão."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q20-p12-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-21","exam":"pcmg2021","number":21,"subject":"Noções de Direito","text":"Quanto a Constituição do Estado de Minas Gerais, é CORRETO afirmar:","options":{"A":" Dentre os direitos e garantias fundamentais assegurados pela Constituição do Estado de Minas Gerias, temos a preservação dos interesses gerais e coletivos.","B":" Os cargos, funções e empregos públicos são acessíveis aos brasileiros na- tos que preencham os requisitos estabelecidos em lei.","C":" Os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não podem ser superiores aos percebidos no Poder Executivo.","D":" São símbolos do Estado de Minas Gerais, a bandeira, o hino e o selo oficial, todos definidos em Lei."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q21-p13-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-22","exam":"pcmg2021","number":22,"subject":"Noções de Direito","text":"A Lei Orgânica da Polícia Civil estabelece que nossa Instituição é um órgão autô-\nnomo, essencial à segurança pública, à realização da justiça e à defesa das insti-\ntuições democráticas cabendo-lhe o exercício de funções específicas, EXCETO:","options":{"A":" A apuração das infrações penais e dos atos infracionais, exercício da polícia judiciária e cooperação com as autoridades judiciárias, civis e militares, em assuntos de segurança interna.","B":" A integração com órgãos de segurança pública do Sistema de Defesa So- cial.","C":" A preservação da ordem e da segurança públicas.","D":" A proteção da incolumidade das pessoas e do patrimônio."},"key":null,"annulled":true,"originalImages":["../assets/questions/pcmg-2021-q22-p13-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Questão oficialmente anulada; não entra no aproveitamento."},{"id":"pcmg2021-23","exam":"pcmg2021","number":23,"subject":"Noções de Direito","text":"A Lei 8.072/90, conhecida por “Lei dos Crimes Hediondos”, tem fundamento cons-\ntitucional no art. 5, XLIII de nossa Constituição Federal e sofreu modificações em\nrazão do “Pacote Anti-crime”, Lei 13.964/19, de autoria do então Ministro Sérgio\nMoro. O critério adotado no Brasil para se definir se um crime é hediondo ou não\né o Critério Legal, através do qual será hediondo apenas aquele que o legislador\ncriminosas tidas por hediondas e, por isso, são mais severamente tratadas.\nDiante disso, é CORRETO afirmar:","options":{"A":" Em razão da Lei 13.964/19, os condenados por crimes hediondos passaram a cumprir a pena em regime integralmente fechado.","B":" Os crimes hediondos, assim definidos pela Lei 8.072/90, são insuscetíveis de liberdade provisória.","C":" São exemplos de crimes hediondos o homicídio qualificado, a extorsão me- diante sequestro, o estupro e o estupro de vulnerável.","D":" Tráfico de entorpecentes, Terrorismo e Tortura são crimes hediondos."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q23-p13-0.webp","../assets/questions/pcmg-2021-q23-p14-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-24","exam":"pcmg2021","number":24,"subject":"Noções de Direito","text":"A Lei 11.340/06, conhecida por “Lei MARIA DA PENHA”, tem base no art. 226, §\n8º da Constituição Federal, in verbis: “O Estado assegurará assistência à família\nna pessoa de cada um dos que a integram, criando mecanismos para coibir a vio-\nlência no âmbito de suas relações”, tendo por inovação o instituto das “medidas\nprotetivas” à mulher vítima de violência doméstica.\nSobre tal instituto, é INCORRETO afirmar:","options":{"A":" As medidas protetivas de urgência poderão ser concedidas de imediato, in- dependentemente de audiência das partes, com a devida manifestação do Ministério Público, posto que o mesmo é custos legis.","B":" O delegado de polícia, onde não tiver juiz, caso haja risco atual ou iminente à vida ou à integridade física da mulher, poderá conceder.","C":" O juiz poderá determinar o afastamento da ofendida do lar, sem prejuízo dos direitos relativos a bens, guarda dos filhos e alimentos.","D":" Para garantir a efetividade das medidas protetivas de urgência, poderá o juiz requisitar, a qualquer momento, auxílio da força policial."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q24-p14-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-25","exam":"pcmg2021","number":25,"subject":"Noções de Direito","text":"A respeito dos Fatos Jurídicos, disciplinados no Livro III, Título I, Capítulos I, II, III\ne IV do Código Civil Brasileiro, é CORRETO afirmar:","options":{"A":" São anuláveis os negócios jurídicos, quando as declarações de vontade emanarem de erro substancial que poderia ser percebido por pessoa de di- ligência normal, em face das circunstâncias do negócio.","B":" A transmissão errônea da vontade por meios interpostos é nula nos mesmos casos em que o é a declaração direta.","C":" Os negócios jurídicos entre vivos, sem prazo, são exequíveis desde logo, salvo apenas se a execução tiver de ser feita em lugar diverso.","D":" O falso motivo sempre vicia a declaração de vontade."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q25-p15-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-26","exam":"pcmg2021","number":26,"subject":"Noções de Direito","text":"Sobre as etapas que envolvem a “Cadeia de Custódia”, é CORRETO afirmar:","options":{"A":" Processamento é o exame pericial em si, manipulação do vestígio de acordo com a metodologia adequada às suas características biológicas, físicas e químicas, a fim de se obter o resultado desejado, que deverá ser formalizado em laudo produzido por perito.","B":" Isolamento é o ato de preservar o local mediato do crime, a fim de que seja maculado por terceiros.","C":" Fixação é a descrição superficial e genérica dos vestígios, feita pelo Agente de Aplicação da Lei que primeiro chega ao local do crime.","D":" Reconhecimento é o ato de identificar um elemento que venha a dispensar a prova pericial e, por isso, não deve ser coletado."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q26-p15-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-27","exam":"pcmg2021","number":27,"subject":"Noções de Direito","text":"A Parte Especial de nosso Código Penal começa com o crime de homicídio (art.\n121 CP), demonstrando a preocupação do nosso legislador em proteger penal-\nmente a vida do ser humano. NÃO corresponde a uma modalidade de homicídio\nqualificado o praticado","options":{"A":" à traição, de emboscada ou mediante dissimulação ou outro recurso que dificulte ou torne impossível a defesa do ofendido.","B":" contra a mulher, por razões da condição de sexo feminino.","C":" contra pessoa menor de 14 anos ou maior de 60 anos.","D":" mediante paga ou promessa de recompensa."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q27-p16-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-28","exam":"pcmg2021","number":28,"subject":"Noções de Direito","text":"Durante a campanha de vacinação contra a COVID-19, a enfermeira municipal\nDoroteia Cajazeira, ficou responsável por vacinar os idosos de uma clínica geriá-\ntrica custeada pelo município de Sucupira do Norte. Para tanto, recebeu 100 (cem)\ndoses de vacina para ministrar em tais idosos. Como a pandemia estava no seu\nauge, e seu amado amante, Odorico Paraguaçu, não estava na lista de vacinação,\nDoroteia retirou uma das doses que seria ministrada, a levou para casa e, na ca-\nlada da noite, ministrou em seu amante, enquanto ele dormia no leito conjugal. No\ndia seguinte, a supervisora de tal asilo descobriu que um dos idosos não havia sido\nimunizado, e procurou pela Secretária de Saúde do município, a qual levou tais\nfatos ao conhecimento do delegado da comarca, que, por sua vez, determinou a\ninstauração de inquérito policial. Ao ser ouvida, em cartório, Doroteia, confessou\nos fatos acima narrados, declarando que tomara tal atitude, a fim de imunizar seu\ngrande amor, e como ele possui aversão à injeção, o vacinou enquanto repousava.\nEm relação aos fatos narrados, é CORRETO afirmar:","options":{"A":" Doroteia Cajazeira praticou o delito de peculato desvio (art. 312, segunda parte do caput CP), uma vez que, agindo como se fosse dono, desviou a dose de vacina em proveito próprio ou alheio.","B":" Doroteia Cajazeira praticou o delito de peculato furto (art. 312, primeira parte do caput CP), uma vez que se valeu de sua condição de funcionária pública para subtrair a dose de vacina, bem que lhe era confiado.","C":" Doroteia Cajazeira teria praticado o crime de furto qualificado por abuso de confiança (art. 155, § 4º, II CP).","D":" Doroteia Cajazeira teria praticado o crime de prevaricação imprópria (art. 319-A CP), uma vez que deixou de praticar ato de ofício para atender a um sentimento pessoal."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q28-p16-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-29","exam":"pcmg2021","number":29,"subject":"Noções de Direito","text":"Relativamente ao tema dos crimes contra a pessoa, contra o Patrimônio, contra a\nDignidade Sexual, contra Administração Pública e Violência Doméstica, analise as\nafirmativas a seguir, as quais correspondem à imagem abaixo.\nI. A imagem é de um funcionário público estadual que, sem autorização, faz\na inserção de dados falsos em sistema de informações do Governo, o que\ncaracterizaria uma das modalidades de peculato.\nII. A imagem é de um funcionário público estadual que, utilizando do seu co-\nnhecimento em informática, acessa o computador de uma modelo famosa\ne passa a exigir-lhe dinheiro sob a ameaça de divulgar ao seu esposo que\nela possui um relacionamento extraconjugal com uma conhecida lutadora\nde sumô, o que caracterizaria o delito de furto eletrônico, nos termos do\nart. 155, § 4º B do Código Penal.\nIII. A imagem é de um funcionário público estadual que, utilizando do seu co-\nnhecimento em informática, acessa o computador de um jovem violinista\ne passa a assediá-lo com o intuito de manterem relação sexual, o que\ncaracterizaria o delito de assédio sexual, nos termos do art. 216-A do Có-\ndigo Penal.\nIV. A imagem é de um funcionário público estadual que, utilizando do seu co-\nnhecimento em informática, acessa do computador de uma cantora as\nsuas redes sociais e e-mail’s, de forma a persegui-la virtualmente, pertur-\nbando sua privacidade, o que caracterizaria o crime de perseguição ou\n“stalking”, nos termos do art. 147-A do Código Penal.\nV. A imagem é de um funcionário público estadual que, utilizando do seu co-\nnhecimento em informática, acessa o computador de sua ex-namorada e,\ninconformado com o fim do namoro, passa a importuná-la, ameaçando-a,\nhumilhando-a com efetivo prejuízo a sua saúde psicológica e autodetermi-\nnação, o que caracterizaria o delito de violência psicológica, nos termos\ndo art. 147-B do Código Penal.","options":{"A":" I, II e IV.","B":" I, IV e V.","C":" II, III e IV.","D":" II, III e V."},"key":null,"annulled":true,"originalImages":["../assets/questions/pcmg-2021-q29-p17-0.webp","../assets/questions/pcmg-2021-q29-p18-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Questão oficialmente anulada; não entra no aproveitamento."},{"id":"pcmg2021-30","exam":"pcmg2021","number":30,"subject":"Noções de Direito","text":"“Os princípios devem ser encarados como normas gerais coercitivas que orientam\na atuação do indivíduo, definindo valores a serem observados nas condutas por\nele praticadas. De fato, os princípios encerram ideias centrais de um sistema e dão\nsentido lógico e harmônico às demais normas que regulamentam o Direito Admi-\nnistrativo, possibilitando sua melhor organização. Por seu turno, os princípios de\nDireito Administrativo definem a organização e a forma de atuar do ente estatal,\nestabelecendo o sentido geral de sua atuação.” (Matheus Carvalho in Manual de\nDireito Administrativo).\nEm relação ao tema “Princípios da administração pública”, é INCORRETO afirmar:","options":{"A":" A atuação estatal pode ser, expressa ou implicitamente, prevista em lei, di- ante da possibilidade de edição de atos administrativos discricionários nos quais o administrador poderá, mediante interpretação baseada no princípio da razoabilidade, definir a possibilidade de atuação, inferido de uma dispo- sição normativa.","B":" O Princípio da Indisponibilidade do Interesse Público define os limites da atuação administrativa e decorre do fato de que a impossibilidade de abrir mão do interesse público deve estabelecer ao administrador os seus crité- rios de conduta.","C":" Pelo princípio da intranscendência, a nomeação de particular para assunção de cargos de natureza política ou a nomeação de parentes para o exercício de função pública é considerada ofensa direta à impessoalidade da atuação estatal.","D":" São princípios constitucionais expressos: Legalidade, Impessoalidade, Mo- ralidade, Publicidade e Eficiência."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q30-p18-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-31","exam":"pcmg2021","number":31,"subject":"Direitos Humanos","text":"“O grande movimento que eclodiu na França em 1789 veio operar, na palavra re-\nvolução, uma mudança semântica de 180º. Desde então, o termo passou a ser\nusado para indicar uma renovação completa das estruturas sociopolíticas. A ins-\ntauração ex novo não apenas de um governo ou de um regime político, mas de\ntoda uma sociedade, no conjunto das relações de poder que compõem a sua es-\ntrutura. Os revolucionários já não são os que se revoltam para restaurar a antiga\nordem política, mas os que lutam com todas as armas – inclusive e sobretudo a\nviolência – para induzir o nascimento de uma sociedade sem precedentes históri-\ncos”. (COMPARATO, Fábio Konder. A Afirmação Histórica dos Direitos Humanos,\n2019, 12ª ed. p. 141).\nSobre a Revolução Francesa de 1789 e sua contribuição para a construção histó-\nrica dos Direitos Humanos, é correto afirmar, EXCETO:","options":{"A":" A Declaração Francesa dos Direitos do Homem e do Cidadão, de 1789, pode ser considerada como a primeira das Declarações de Direitos com vo- cação universal.","B":" Apesar de não incorporar ideais jusnaturalistas, a Declaração dos Direitos do Homem e do Cidadão de 1789 foi responsável por redefinir a relação entre o indivíduo e o estado, transformando o súdito em cidadão.","C":" Entre os direitos previstos na Constituição Francesa de 1791 estão a sobe- rania popular, o sistema de governo representativo, a igualdade de todos perante a lei, a presunção de inocência e o voto censitário.","D":" Importante marco para o desenvolvimento futuro dos direitos humanos, foi o projeto de Declaração dos Direitos da Mulher e da Cidadã, de 1791, pro- posto por Olympe de Gouges, que reivindicou a igualdade de direitos de gênero."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q31-p19-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-32","exam":"pcmg2021","number":32,"subject":"Direitos Humanos","text":"Considerando a afirmação histórica dos direitos humanos, analise os itens a se-\nguir:\nI-\nPromulgado exatamente um século antes da revolução francesa, o Bill\nof Rights (1689) pôs fim, pela primeira vez, desde o seu surgimento\nna Europa renascentista, ao regime da monarquia absoluta, no qual\ntodo poder emana do rei e em seu nome é exercido.\nII- Na Declaração dos Direitos do Homem e do Cidadão (1789) fixou-se,\nno campo penal, que não há crime sem lei anterior que o define, nem\npena que não seja fixada em lei.\nIII- A Carta Política Russa de 1917 foi a primeira a atribuir aos direitos\ntrabalhistas a qualidade de direitos fundamentais, juntamente com as\nliberdades individuais e os direitos políticos.\nEstá CORRETO o que se afirma em:","options":{"A":" I, apenas.","B":" I e II, apenas.","C":" I e III, apenas.","D":" I, II e III."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q32-p20-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-33","exam":"pcmg2021","number":33,"subject":"Direitos Humanos","text":"O Tratado de Versalhes de 1919 é o documento que consolida os termos de paz\nda Primeira Guerra Mundial e que trouxe contribuições para o processo de inter-\nnacionalização dos Direitos Humanos no século XX. Entre essas contribuições\nestá:","options":{"A":" A criação da Organização Internacional do Trabalho, responsável por esta- belecer critérios básicos de proteção ao trabalhador, regulando sua condi- ção no plano internacional, tendo em vista assegurar padrões mais condi- zentes de dignidade e de bem-estar social.","B":" A criação de obrigação aos Estados membros de instituírem ações para re- dução da miséria e desigualdade social, como forma de evitar a eclosão de movimentos revolucionários, como o caso russo em 1918.","C":" A criação dos primeiros dispositivos do Direito Internacional Humanitário para a limitação à soberania estatal diante de conflitos armados, discipli- nando o incipiente direito de guerra.","D":" A instituição de cláusulas de proteção às pessoas refugiadas, em razão da experiência vivenciada com a migração resultante das disputas imperialistas no território africano."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q33-p20-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-34","exam":"pcmg2021","number":34,"subject":"Direitos Humanos","text":"Nos termos da Constituição Federal de 1988, são princípios fundamentais, EX-\nCETO:","options":{"A":" Autodeterminação dos povos.","B":" Garantia do desenvolvimento nacional.","C":" Os valores sociais do trabalho e da livre iniciativa.","D":" Soberania popular."},"key":"D","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q34-p21-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa D. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-35","exam":"pcmg2021","number":35,"subject":"Direitos Humanos","text":"“Instituição, no âmbito do sistema interamericano, responsável pelo recebimento\nde denúncias ou queixas de violações de direitos humanos deflagradas por indiví-\nduos ou por organizações não governamentais contra atos dos Estados.”\nA instituição a que o texto faz referência é a","options":{"A":" Comissão Interamericana de Direitos Humanos.","B":" Comissão Jurídica Interamericana.","C":" Corte Interamericana de Direitos Humanos.","D":" Organização dos Estados Americanos."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q35-p21-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-36","exam":"pcmg2021","number":36,"subject":"Direitos Humanos","text":"A respeito da proteção internacional da pessoa idosa, NÃO é correto afirmar:","options":{"A":" A Convenção Interamericana sobre a Proteção dos Direitos Humanos dos Idosos estabelece sistema de petições individuais à Comissão Interameri- cana de Direitos Humanos, para informações sobre violações realizadas por algum Estado Parte.","B":" A Convenção Interamericana sobre a Proteção dos Direitos Humanos dos Idosos foi incorporada ao direito brasileiro apenas com status supralegal, haja vista que ainda não ocorreu a ratificação do tratado pelo governo bra- sileiro, apenas sua assinatura.","C":" Há previsão, no “Protocolo de San Salvador”, de disposição relativa à pro- teção das pessoas idosas, garantindo o direito de que toda pessoa tenha proteção especial na velhice.","D":" Não há, no plano global de proteção, instrumentos jurídicos de hard law que padronizem os direitos dos idosos, o que leva a crer que os direitos humanos dessa categoria de pessoas não têm tido o destaque merecido no atual di- reito internacional público."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q36-p21-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-37","exam":"pcmg2021","number":37,"subject":"Direitos Humanos","text":"Nos termos do art. 6º da Constituição Federal de 1988, são direitos sociais:","options":{"A":" A educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a previdência social, a proteção à maternidade e à in- fância, a assistência aos desamparados.","B":" A educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança pública, a assistência social, a proteção à maternidade e à infância, a assistência aos desamparados.","C":" A educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a assistência social, a proteção à maternidade e à infân- cia, a assistência aos desamparados, na forma desta Constituição.","D":" A educação, a saúde, o trabalho, a moradia, o transporte, o lazer, a segu- rança, a assistência social, a proteção à maternidade e à infância, a assis- tência aos desamparados."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q37-p22-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-38","exam":"pcmg2021","number":38,"subject":"Direitos Humanos","text":"A respeito da Convenção Interamericana Contra o Racismo, a Discriminação Ra-\ncial e Formas Correlatas de Intolerância (2013), NÃO é correto afirmar:","options":{"A":" Considera discriminação racial qualquer distinção, exclusão, restrição ou preferência, em qualquer área da vida pública ou privada, cujo propósito ou efeito seja anular ou restringir o reconhecimento, gozo ou exercício, em con- dições de igualdade, de um ou mais direitos humanos e liberdades funda- mentais consagrados nos instrumentos internacionais aplicáveis aos Esta- dos Partes.","B":" Foi aprovada em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros e promulgada pelo Decreto Legislativo 01/2021.","C":" Foi promulgada pelo Presidente da República em junho de 2021, o que trouxe plena eficácia à norma no âmbito do direito brasileiro.","D":" Foi ratificada pelo Presidente da República em maio de 2021."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q38-p22-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-39","exam":"pcmg2021","number":39,"subject":"Direitos Humanos","text":"Sobre a organização da Corte Interamericana de Direitos Humanos, é correto afir-\nmar, EXCETO:","options":{"A":" A Comissão comparecerá em todos os casos perante a Corte.","B":" A Corte compor-se-á de sete juízes, nacionais dos Estados Membros da Organização, eleitos a títulos pessoal dentre juristas da mais alta autoridade moral, de reconhecida competência em matéria de direitos humanos, que reúnam as condições requeridas para o exercício das mais elevadas fun- ções judiciais, de acordo com a lei do Estado do qual sejam nacionais, ou do Estado que os propuser como candidatos.","C":" O juiz que for nacional do Estado-Parte que propôs o caso submetido à Corte não terá o direito de conhecer o mesmo.","D":" Os juízes da Corte serão eleitos, em votação secreta e pelo voto da maio- ria absoluta dos Estados-Partes na Convenção, na Assembleia-Geral da Organização, de uma lista de candidatos propostos pelos mesmos Esta- dos."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q39-p23-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-40","exam":"pcmg2021","number":40,"subject":"Direitos Humanos","text":"Sobre o Alto Comissariado das Nações Unidas, é INCORRETO afirmar:","options":{"A":" Compõe a estrutura do Secretariado-Geral da ONU e possui sede em Ge- nebra (Suíça).","B":" Entre seus objetivos está manter a paz e a segurança internacionais.","C":" Foi criado por meio da Resolução 48/141 da Assembleia Geral da ONU, de 20 de dezembro de 1993, objetivando focar os esforços e dar sinergia às atividades das Nações Unidas na área dos direitos humanos.","D":" O Alto Comissário é indicado pelo Secretário-Geral das Nações Unidas e aprovado pela Assembleia Geral, tendo em conta uma alternância geográ- fica, para um mandato de quatro anos, renovável uma vez por mais quatro."},"key":null,"annulled":true,"originalImages":["../assets/questions/pcmg-2021-q40-p23-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Questão oficialmente anulada; não entra no aproveitamento."},{"id":"pcmg2021-41","exam":"pcmg2021","number":41,"subject":"Informática","text":"Ao acessar a opção “Privacidade” na janela “Configurações” do Microsoft Win-\ndows 10, versão português, é possível fazer configurações para aumentar o nível\nde privacidade dos usuários.\nAnalise as opções abaixo sobre as funcionalidades da opção “Privacidade” da ja-\nnela “Configurações” do Microsoft Windows 10:\nI – Na opção “Câmera”, é possível definir quais aplicativos poderão utilizar\na câmera do computador.\nII – Na opção “Localização”, é possível ativar o serviço de localização do\ncomputador e ainda definir quais aplicativos poderão utilizar esse\nserviço.\nIII – Na opção “Contatos”, é possível definir quais usuário poderão ter\nacesso ao computador.\nEstão CORRETAS as afirmativas:","options":{"A":" I e II, apenas.","B":" I e III, apenas.","C":" I, II e III.","D":" II e III, apenas."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q41-p24-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-42","exam":"pcmg2021","number":42,"subject":"Informática","text":"O DHCP é um Protocolo de Configuração Dinâmica de Endereços de Rede.\nTodas as afirmativas abaixo sobre o DHCP estão corretas, EXCETO:","options":{"A":" O DHCP é um protocolo cliente/servidor.","B":" O DHCP se baseia na ideia de um servidor especial que atribui endereços IP a hosts que solicitam um endereço.","C":" O servidor DHCP precisa estar na mesma LAN em que se encontra o host solicitante.","D":" Sem o DHCP, os endereços IP para novos computadores precisam ser con- figurados manualmente."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q42-p24-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-43","exam":"pcmg2021","number":43,"subject":"Informática","text":"Analise as seguintes afirmativas sobre as funções disponíveis no LibreOffice Calc\n7.1.6, versão português:\nI –\nA função ARRED(número; contagem) arredonda um número com\nexatidão predefinida.\nII –\nA função AGORA() retorna apenas hora atual do computador.\nIII –\nA função CONCAT(Texto1; Texto2; ...) concatena vários itens de\ntexto em apenas um e aceita intervalos de células como argumen-\ntos.\nEstá CORRETO apenas o que se afirma em:","options":{"A":" I.","B":" I e III.","C":" II e III.","D":" III."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q43-p25-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-44","exam":"pcmg2021","number":44,"subject":"Informática","text":"PGP (Pretty Good Privacy) é um padrão de criptografia que fornece privacidade e\nautenticidade dos dados enviados e recebidos.\nTodas as afirmativas sobre o padrão PGP estão corretas, EXCETO:","options":{"A":" A chave principal do padrão PGP é a chave pública e não deve ser distribu- ída.","B":" PGP é um sistema de criptografia híbrido, que combina criptografia com chave privada e criptografia com chave pública.","C":" PGP faz compressão de dados, reduzindo o tempo de transmissão e o es- paço em disco ocupado.","D":" PGP utiliza um par de chaves assimétricas."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q44-p25-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-45","exam":"pcmg2021","number":45,"subject":"Informática","text":"Os malwares, cujo termo é proveniente de “Malicious Software” (software malici-\noso), são ameaças virtuais desenvolvidas com o intuito de executar atividades\nmaliciosas em computadores e smartphones.\nO malware que se caracteriza por manipular o tráfego de um site legítimo para di-\nrecionar usuários para sites falsos por meio da técnica de envenenamento do ca-\nche DNS é o:","options":{"A":" Cavalo de Troia.","B":" Pharming.","C":" Ransomware.","D":" Spyware."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q45-p26-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-46","exam":"pcmg2021","number":46,"subject":"Informática","text":"A Lei Nº 12.965 de 23 de abril de 2014, também conhecida como Marco Civil da\nInternet, estabelece princípios, garantias, direitos e deveres para o uso da inter-\nnet no Brasil.\nConsiderando os princípios que disciplina o uso da internet no Brasil, definidos\nno Art. 3º da referida lei, analise os princípios a seguir e identifique-os com (V) ou\n(F) conforme sejam verdadeiros ou falsos.\n(   )  Preservação e garantia da parcialidade de rede.\n(   )  Proteção da privacidade.\n(   )  Proteção dos dados pessoais, na forma da lei.\n(   )  Restrição à comunicação e manifestação de pensamento.\nA sequência CORRETA, de cima para baixo, é:","options":{"A":" F, F, V, F.","B":" F, V, V, F.","C":" V, F, V, V.","D":" V, V, F, V."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q46-p26-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-47","exam":"pcmg2021","number":47,"subject":"Informática","text":"Chama-se topologia de uma rede a distribuição geográfica de seus nodos (equi-\npamentos) e elos (canais de comunicação).\nSobre as topologias físicas de rede mais comumente utilizadas, considere as se-\nguintes afirmativas:\n(I)\nTopologia em barramento (bus) – usa um único cabo backbone que é\nterminado em ambas as extremidades. Todos os hosts são diretamente\nconectados a esse barramento.\n(II)\nTopologia em malha (mesh) – conecta um host ao próximo e o último\nhost ao primeiro.\n(III) Topologia em anel (ring) – cada host tem suas próprias conexões com\ntodos os outros hosts.\nEstá CORRETO o que se afirma em:","options":{"A":" I, apenas.","B":" I e II, apenas.","C":" I e III, apenas.","D":" I, II e III."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q47-p27-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-48","exam":"pcmg2021","number":48,"subject":"Informática","text":"Os navegadores web, ou web browsers, se comunicam geralmente com servido-\nres web através de protocolos.\nSão exemplos de protocolos de transferência suportados pelos navegadores\nweb, EXCETO:","options":{"A":" FTP.","B":" HTML.","C":" HTTP.","D":" HTTPS."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q48-p27-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-49","exam":"pcmg2021","number":49,"subject":"Informática","text":"A técnica de criptografia consiste na utilização de métodos de modificação de\ntextos, visando a não os transmitir em sua forma clara e, assim, protegê-los pre-\nventivamente em relação à eventual interceptação.\nSobre o uso de criptografia e certificados digitais, considere as seguintes afirmati-\nvas:\n(I)\nUm método de criptografia que utiliza uma mesma chave na origem e no\ndestino (para codificar e decodificar) é denominado método simétrico ou\nbaseado em chave secreta.\n(II)\nNos métodos de criptografia assimétricos ou baseados em chave pú-\nblica, todos os usuários tornam públicas suas chaves de codificação e\nmantêm privadas suas chaves de decodificação.\n(III) A ICP–Brasil tem por objetivo garantir a autenticidade, a integridade e a\nvalidade jurídica de documentos eletrônicos que utilizam certificados di-\ngitais.\nEstá CORRETO o que se afirma em:","options":{"A":" I e III, apenas.","B":" II e III, apenas.","C":" III, apenas.","D":" I, II e III."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q49-p28-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-50","exam":"pcmg2021","number":50,"subject":"Informática","text":"Em relação às opções do grupo “Iniciar Apresentação de Slides” da guia “Apre-\nsentação de Slides” do Microsoft PowerPoint, versão português do Office 2016,\ncorrelacione as colunas a seguir:\nÍcone da opção\nOpção\n(    )   Apresentar Online.\nI.\n(    )   Do Slide Atual.\nII.\n(    )   Apresentação de Slides Personalizada.\nIII.\n(    )   Do Começo.\nIV.\nA sequência que expressa a correlação CORRETA, de cima para baixo, é:","options":{"A":" III, I, IV, II.","B":" III, II, IV, I.","C":" IV, I, III, II.","D":" IV, II, III, I."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q50-p29-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-51","exam":"pcmg2021","number":51,"subject":"Criminologia","text":"Isabela, Investigadora de Polícia Civil do Estado de Minas Gerais, participava de\num curso de especialização quando se deparou com a argumentação de um pro-\nfessor que, após a projeção da imagem de uma pessoa no quadro, começou a\nexplicar:\n“Percebam as rugas frontais existentes na face desse indivíduo. É verda-\ndeiramente típico o modo de se apresentar a característica destas rugas\nem alguns criminosos ainda jovens. São tão profundas que a fronte se\napresenta, em tais casos, reiteradamente pregada, ou com uma incisão\ncomo uma ferida proveniente de um corte.”\nAtenta, Isabela logo concluiu que a argumentação do docente se correlacionava\nao pensamento criminológico de","options":{"A":" Cesare Lombroso.","B":" Enrico Ferri.","C":" Francesco Carrara.","D":" Rafaelle Garofalo."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q51-p30-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-52","exam":"pcmg2021","number":52,"subject":"Criminologia","text":"Sobre a teoria estrutural funcionalista da anomia e da criminalidade, analise as\nassertivas abaixo:\nI. As causas do desvio não devem ser pesquisadas nem em fatores bioan-\ntropológicos e naturais (clima, raça), nem em uma situação patológica da\nestrutura social.\nII. O desvio é um fenômeno normal de toda estrutura social.\nIII. Somente quando são ultrapassados determinados limites, o fenômeno do\ndesvio é negativo para a existência e o desenvolvimento da estrutura so-\ncial.","options":{"A":" I e II, apenas.","B":" I e III, apenas.","C":" I, II e III.","D":" II e III, apenas."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q52-p30-0.webp","../assets/questions/pcmg-2021-q52-p31-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-53","exam":"pcmg2021","number":53,"subject":"Criminologia","text":"Analise o trecho abaixo:\n“[...] o fundamento mais geral do ato desviado deve ser investigado junto às bases\nestruturais econômicas e sociais que caracterizam a sociedade na qual vive o autor\ndo delito. A proposta desta teoria para o processo criminalizador objetiva reduzir\nas desigualdades das classes sociais dominantes, como a criminalidade econô-\nmica e política, práticas antissociais na área de segurança do trabalho, da saúde\npública, do meio ambiente, da economia popular, do patrimônio coletivo estatal e\ncontra o crime organizado, com uma maximização da intervenção punitiva; de ou-\ntro lado, há de se fazer uma minimização da intervenção punitiva para pequenos\ndelitos, crimes patrimoniais (cometidos sem violência ou grave ameaça à pessoa),\ndelitos que envolvem questões morais e uso de entorpecentes.” (SCHECAIRA, Sérgio\nSalomão. Criminologia, 4. ed. São Paulo: Revista dos Tribunais, 2012, p. 315)\nO postulado teórico constante do trecho acima trata-se da:","options":{"A":" Criminologia crítica.","B":" Escola de Chicago.","C":" Teoria da anomia.","D":" Teoria da associação diferencial."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q53-p31-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-54","exam":"pcmg2021","number":54,"subject":"Criminologia","text":"De acordo com Marcos Rolim:\n“[...] as polícias modernas não surgiram como resultado de uma preocupação es-\npecial com a ocorrência de crimes. Tampouco foram a consequência de uma as-\npiração disseminada socialmente. Entre os historiadores, a opinião mais comum é\na de que o fator imediato responsável pela formação das modernas forças de ‘po-\nlícia’ foi a emergência de um sem-número de revoltas populares e desordens de\nrua na maior parte dos países europeus e a incapacidade dos governos para con-\ntinuarem lidando com elas através da convocação de tropas do exército. O recurso\nhavia já se mostrado inadequado, não apenas pela sucessão de cenas violentas\ne de mortes que provocava, mas, sobretudo – na sensibilidade dos governantes\nda época – porque não se conseguia ‘resolver’ o problema daquela forma. [...] O\nproblema, entretanto, seria reposto logo adiante com novas manifestações e de-\nsordens. Era preciso, então, uma estrutura ‘permanecente’ e profissional que ti-\nvesse sempre nas ruas. Foi assim que nasceram as polícias modernas.” (ROLIM,\nMarcos. A síndrome da rainha vermelha: policiamento e segurança pública no século XXI. Rio de\nJaneiro: Jorge Zahar, 2006, p. 25).\nSobre os pressupostos de instituição das polícias como forma de controle social\nformal do crime, analise as assertivas abaixo:\nI. O surgimento das forças policiais modernas no Ocidente foi um fenômeno\ndo século XIX, de forma que, até então, as funções policiais eram exerci-\ndas de maneira assistemática por grupos de cidadãos convocados, por\nvoluntários ou pessoas comissionadas pelos governos, as quais exerciam\nas funções de natureza fiscalizatória.\nII. Até o século XIX, a história da polícia não poderá ser contada em termos\ninstitucionais, porque a organização típica de policiamento ainda não exis-\ntia, como regra, de forma autônoma.\nIII. A ausência de uma instituição policial profissional e dedicada exclusiva-\nmente às funções de segurança pública explica-se pelo fato de que o pró-\nprio conceito de segurança pública não faria qualquer sentido para além\nda ideia de manutenção da paz em sociedades em que as funções da\npersecução e a própria aplicação da justiça criminal eram, normalmente,\nconsideradas questões privadas.","options":{"A":" I e II, apenas.","B":" I e III, apenas.","C":" I, II e III.","D":" II e III, apenas."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q54-p32-0.webp","../assets/questions/pcmg-2021-q54-p33-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-55","exam":"pcmg2021","number":55,"subject":"Criminologia","text":"Marcos Rolim assegura que “qualquer que seja o olhar sobre o funcionamento do\nsistema de justiça criminal em todo o mundo, ele terá de conter, pelo menos, dúvi-\ndas muito consistentes a respeito de sua eficácia. Pode-se, com razão, argumentar\nque a experiência concreta realizada com a justiça criminal na modernidade está\nmarcada por promessas não cumpridas que vão desde a alegada função dissua-\nsória ou intimidadora das penas até a perspectiva da ressocialização” (ROLIM, Mar-\ncos. A síndrome da rainha vermelha: policiamento e segurança pública no século XXI. Rio de Janeiro:\nJorge Zahar, 2006, p. 233).\nNesse sentido, tendo como referência o paradigma da justiça restaurativa como\nforma de eficácia do controle social formal do crime, é correto afirmar, EXCETO:","options":{"A":" Foco na solução do problema; atenção direcionada para o futuro (o que pode ser feito?).","B":" O crime é definido como violação do Estado, de forma que a natureza inter- pessoal do conflito é obscurecida.","C":" O papel da vítima e dos infratores é reconhecido: as necessidades das víti- mas são reconhecidas e os infratores são estimulados a assumir responsa- bilidades.","D":" Responsabilização do infrator definida a partir do entendimento do mal cau- sado e da decisão de reparar o dano."},"key":"B","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q55-p33-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa B. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-56","exam":"pcmg2021","number":56,"subject":"Medicina Legal","text":"A lesão caracteristicamente causada pelo projétil de arma de fogo é:","options":{"A":" contusa.","B":" perfurante.","C":" pérfuro-contusa.","D":" pérfuro-incisa."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q56-p34-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-57","exam":"pcmg2021","number":57,"subject":"Medicina Legal","text":"Mulher de 79 anos teve mal súbito, de causa indeterminada, tendo sido socorrida\ne levada ao pronto atendimento pelo SAMU. Chegou em parada cardiorrespiratória\n(PCR) e óbito. Como antecedente, era hipertensa, diabética II insulinodependente\ne teve queda da própria altura há 1 ano, no quarto, com fratura de pelve, sendo\nsubmetida a tratamento cirúrgico. Teve boa recuperação, alta hospitalar, em trata-\nmento fisioterápico e já deambulando normalmente.\nNeste caso, é mais aconselhável que a declaração de óbito seja emitida","options":{"A":" no IML, pelo antecedente de trauma com fratura.","B":" pelo médico do pronto atendimento, que atendeu a paciente em PCR.","C":" pelo médico do SAMU, chamado ao domicílio.","D":" pelo ortopedista, que apenas operou a paciente."},"key":null,"annulled":true,"originalImages":["../assets/questions/pcmg-2021-q57-p34-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Questão oficialmente anulada; não entra no aproveitamento."},{"id":"pcmg2021-58","exam":"pcmg2021","number":58,"subject":"Medicina Legal","text":"Durante uma necropsia, observou-se que o corpo apresentava manchas de hipós-\ntase fixas.\nCom este dado, é CORRETO afirmar que o tempo de morte é, no mínimo, de","options":{"A":" 12 horas.","B":" 2 horas.","C":" 24 horas.","D":" 6 horas."},"key":"A","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q58-p34-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa A. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-59","exam":"pcmg2021","number":59,"subject":"Medicina Legal","text":"Na perícia de local de um cadáver, foi descrito pelo perito que a morte ocorreu pela\nconstrição do pescoço por um laço que exerceu força ativa, ao passo que o corpo\nda vítima atuava de forma passiva. O exame necroscópico identificou fratura de\ncartilagem cricoide e lesão da íntima da carótida interna. Essas informações estão\nrelacionadas à asfixia por","options":{"A":" enforcamento com suspensão típica ou completa.","B":" esganadura.","C":" estrangulamento.","D":" sufocação indireta."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q59-p35-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."},{"id":"pcmg2021-60","exam":"pcmg2021","number":60,"subject":"Medicina Legal","text":"Com relação aos conhecimentos sobre corpo de delito, perito e perícia em medi-\ncina legal e aos documentos médico-legais, é CORRETO afirmar:","options":{"A":" Define-se corpo de delito como o conjunto de vestígios comprobatórios da prática de um crime evidenciado no corpo de uma pessoa.","B":" O atestado médico equipara-se ao laudo pericial, para serventia nos autos de inquéritos e processos judiciais, devendo ambos ser emitidos por perito oficial.","C":" Perícia é o exame determinado por autoridade policial ou judiciária com a finalidade de elucidar fato, estado ou situação no interesse da investigação e da justiça.","D":" Perito oficial é todo indivíduo com expertise técnica na área de sua compe- tência incumbido de realizar o exame."},"key":"C","annulled":false,"originalImages":["../assets/questions/pcmg-2021-q60-p35-0.webp"],"supportImages":[],"needsVisual":true,"explanation":"Gabarito oficial definitivo: alternativa C. Confira o enunciado original e revise o conteúdo; esta questão ainda não tem comentário individual de resolução."}]};
